export const ROCKET_GAME_HTML = "<!DOCTYPE html>\n<html lang=\"cs\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n<title>Vesm\u00edrn\u00fd Ochr\u00e1nce v4.0</title>\n<style>\n:root {\n    --ui: #7c3aed;\n    --ui-dim: #5b3aa8;\n    --danger: #ff0055;\n    --gold: #ffc400;\n    --bg: #020617;\n    --panel: rgba(15, 23, 42, 0.94);\n    --line: rgba(124, 58, 237, 0.18);\n}\n\n* {\n    box-sizing: border-box;\n    user-select: none;\n    -webkit-user-drag: none;\n    -webkit-tap-highlight-color: transparent;\n    margin: 0;\n    padding: 0;\n}\n\nbody, html {\n    width: 100%;\n    height: 100%;\n    background: #000;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n    overflow: hidden;\n    touch-action: none;\n}\n\n#game-container {\n    position: relative;\n    width: 100vw;\n    height: 100%;\n    max-width: 620px;\n    background: var(--bg);\n    overflow: hidden;\n    box-shadow: 0 0 60px rgba(124, 58, 237, 0.12);\n}\n\ncanvas {\n    display: block;\n    width: 100%;\n    height: 100%;\n}\n\n#game-container.playing canvas { cursor: crosshair; }\n\nbutton { font-family: inherit; }\n\nbutton:focus-visible {\n    outline: 2px solid var(--ui);\n    outline-offset: 2px;\n}\n\n/*------ HUD ------*/\n.hud {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    padding: calc(12px + env(safe-area-inset-top, 0px)) 12px 12px;\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    pointer-events: none;\n    z-index: 10;\n}\n\n.hud-top {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 10px;\n}\n\n.hud-group {\n    background: rgba(0, 0, 0, 0.6);\n    padding: 7px 13px;\n    border-radius: 11px;\n    border: 1px solid var(--line);\n    color: #fff;\n    font-weight: 700;\n    font-size: 14px;\n    display: flex;\n    gap: 14px;\n    align-items: baseline;\n    text-shadow: 0 0 6px #000;\n    transition: box-shadow 0.3s, border-color 0.3s;\n}\n\n#hud-score { font-variant-numeric: tabular-nums; }\n#hud-coins { color: var(--gold); font-variant-numeric: tabular-nums; }\n\n#hud-combo {\n    color: #fff;\n    background: var(--danger);\n    border-radius: 7px;\n    padding: 1px 7px;\n    font-size: 13px;\n    box-shadow: 0 0 12px rgba(255, 0, 85, 0.7);\n}\n\n.hud-buttons {\n    display: flex;\n    gap: 7px;\n    pointer-events: auto;\n}\n\n.icon-btn {\n    background: rgba(0, 0, 0, 0.6);\n    border: 1px solid var(--ui-dim);\n    color: var(--ui);\n    border-radius: 9px;\n    width: 40px;\n    height: 36px;\n    font-weight: 700;\n    font-size: 14px;\n    cursor: pointer;\n    transition: transform 0.1s;\n}\n\n.icon-btn:active { transform: scale(0.92); }\n\n/* Pruh \u017eivota: tvar nese informaci l\u00e9pe ne\u017e \u010d\u00edslo v procentech */\n.hp-row {\n    display: flex;\n    align-items: center;\n    gap: 9px;\n    max-width: 260px;\n}\n\n.hp-track {\n    position: relative;\n    flex: 1;\n    height: 13px;\n    background: rgba(0, 0, 0, 0.62);\n    border: 1px solid var(--line);\n    border-radius: 7px;\n    overflow: hidden;\n}\n\n.hp-fill {\n    height: 100%;\n    width: 100%;\n    background: linear-gradient(90deg, #00b34a, #4dff88);\n    transition: width 0.22s ease-out, background 0.3s;\n}\n\n.hp-fill.mid { background: linear-gradient(90deg, #b37700, #ffc400); }\n.hp-fill.low { background: linear-gradient(90deg, #99002f, #ff2a5f); }\n\n/* D\u00edlky po 25 % d\u00e1vaj\u00ed pruhu m\u011b\u0159\u00edtko */\n.hp-ticks {\n    position: absolute;\n    inset: 0;\n    background-image: linear-gradient(90deg, transparent calc(25% - 1px), rgba(0, 0, 0, 0.55) calc(25% - 1px), rgba(0, 0, 0, 0.55) 25%, transparent 25%);\n    background-size: 25% 100%;\n}\n\n.hp-num {\n    color: #fff;\n    font-size: 12px;\n    font-weight: 700;\n    min-width: 46px;\n    font-variant-numeric: tabular-nums;\n    text-shadow: 0 0 6px #000;\n}\n\n/*------ PRUH BOSSE ------*/\n.boss-bar {\n    background: rgba(0, 0, 0, 0.6);\n    border: 1px solid var(--line);\n    border-radius: 10px;\n    padding: 7px 11px 9px;\n    animation: dropIn 0.35s ease-out;\n}\n\n@keyframes dropIn {\n    from { opacity: 0; transform: translateY(-14px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n.boss-head {\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    margin-bottom: 5px;\n}\n\n#boss-name {\n    font-size: 13px;\n    font-weight: 800;\n    letter-spacing: 2px;\n}\n\n#boss-phase {\n    font-size: 11px;\n    color: #9aa1ad;\n}\n\n.boss-track {\n    height: 9px;\n    background: rgba(255, 255, 255, 0.08);\n    border-radius: 5px;\n    overflow: hidden;\n}\n\n.boss-fill {\n    height: 100%;\n    width: 100%;\n    transition: width 0.18s linear;\n}\n\n/*------ ODPO\u010cTY POWER-UP\u016e ------*/\n.powerup-timers {\n    display: flex;\n    gap: 10px;\n}\n\n.buff-badge {\n    position: relative;\n    width: 42px;\n    height: 42px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: rgba(0, 0, 0, 0.6);\n    border-radius: 50%;\n    animation: popIn 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n\n@keyframes popIn {\n    from { transform: scale(0); }\n    to { transform: scale(1); }\n}\n\n.buff-badge svg {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    transform: rotate(-90deg);\n}\n\n.buff-badge circle.bg {\n    stroke: rgba(255, 255, 255, 0.1);\n    stroke-width: 3;\n    fill: none;\n}\n\n.buff-badge circle.progress {\n    stroke-width: 3;\n    fill: none;\n    stroke-dasharray: 100;\n    stroke-dashoffset: 0;\n    stroke-linecap: round;\n}\n\n.buff-icon { font-size: 19px; z-index: 2; }\n\n/*------ BOMBA ------*/\n#btn-bomb {\n    position: absolute;\n    right: calc(16px + env(safe-area-inset-right, 0px));\n    bottom: calc(22px + env(safe-area-inset-bottom, 0px));\n    width: 66px;\n    height: 66px;\n    border-radius: 50%;\n    background: radial-gradient(circle at 34% 30%, rgba(255, 196, 0, 0.32), rgba(0, 0, 0, 0.72));\n    border: 2px solid var(--gold);\n    color: #fff;\n    font-size: 25px;\n    cursor: pointer;\n    z-index: 12;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    box-shadow: 0 0 18px rgba(255, 196, 0, 0.3);\n    transition: transform 0.1s, opacity 0.2s;\n}\n\n#btn-bomb:active { transform: scale(0.9); }\n\n#btn-bomb.empty {\n    opacity: 0.3;\n    border-color: #555;\n    box-shadow: none;\n}\n\n#bomb-count {\n    position: absolute;\n    right: -2px;\n    bottom: -2px;\n    background: var(--gold);\n    color: #1a1200;\n    font-size: 13px;\n    font-weight: 900;\n    min-width: 22px;\n    height: 22px;\n    border-radius: 11px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n/*------ HL\u00c1\u0160EN\u00cd UPROST\u0158ED ------*/\n#event-text {\n    position: absolute;\n    top: 27%;\n    left: 0;\n    width: 100%;\n    text-align: center;\n    font-size: 27px;\n    font-weight: 900;\n    letter-spacing: 3px;\n    opacity: 0;\n    pointer-events: none;\n    z-index: 15;\n    transition: opacity 0.25s, transform 0.25s;\n    transform: scale(0.82);\n    text-shadow: 0 0 18px currentColor;\n}\n\n#event-text.show { opacity: 1; transform: scale(1); }\n\n/*------ MENU & P\u0158EKRYVY ------*/\n.overlay {\n    position: absolute;\n    inset: 0;\n    background: rgba(5, 5, 15, 0.9);\n    backdrop-filter: blur(8px);\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: flex-start;\n    overflow-y: auto;\n    padding: calc(20px + env(safe-area-inset-top, 0px)) 20px calc(20px + env(safe-area-inset-bottom, 0px));\n    text-align: center;\n    z-index: 20;\n    color: #fff;\n}\n\n.overlay > *:first-child { margin-top: auto; }\n.overlay > *:last-child { margin-bottom: auto; }\n\n.hidden { display: none !important; }\n\nh1 {\n    font-size: 34px;\n    letter-spacing: 6px;\n    color: var(--ui);\n    text-shadow: 0 0 22px rgba(124, 58, 237, 0.55);\n    margin-bottom: 4px;\n}\n\nh2 {\n    color: var(--danger);\n    font-size: 27px;\n    letter-spacing: 3px;\n    margin-bottom: 8px;\n}\n\n.tagline {\n    color: #7c8391;\n    font-size: 13px;\n    letter-spacing: 1px;\n    margin-bottom: 18px;\n}\n\n.btn {\n    background: linear-gradient(45deg, #6d28d9, #7c3aed);\n    border: none;\n    color: #fff;\n    padding: 14px 28px;\n    font-size: 16px;\n    font-weight: 700;\n    border-radius: 25px;\n    margin: 7px;\n    cursor: pointer;\n    box-shadow: 0 4px 16px rgba(124, 58, 237, 0.28);\n    transition: transform 0.1s;\n    width: 82%;\n    max-width: 310px;\n}\n\n.btn:active { transform: scale(0.96); }\n\n.btn-danger {\n    background: linear-gradient(45deg, #ff0055, #aa0000);\n    box-shadow: 0 4px 16px rgba(255, 0, 85, 0.28);\n}\n\n.btn-hard { background: linear-gradient(45deg, #ff8800, #ff0055); }\n\n.btn-small {\n    padding: 8px 16px;\n    font-size: 14px;\n    width: auto;\n    margin: 0;\n}\n\n.stats-bar {\n    width: 100%;\n    max-width: 350px;\n    background: var(--panel);\n    padding: 11px;\n    border-radius: 12px;\n    border: 1px solid var(--ui-dim);\n    margin-bottom: 14px;\n    display: flex;\n    justify-content: space-around;\n    font-weight: 700;\n    font-size: 14px;\n}\n\n.section-label {\n    width: 100%;\n    max-width: 350px;\n    text-align: left;\n    font-size: 12px;\n    color: #6c7280;\n    margin-bottom: 7px;\n    letter-spacing: 1px;\n}\n\n.upgrades-container {\n    width: 100%;\n    max-width: 350px;\n    margin-bottom: 14px;\n}\n\n.upgrade-item {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background: var(--panel);\n    padding: 10px 12px;\n    border-radius: 12px;\n    margin-bottom: 8px;\n    border: 1px solid var(--line);\n    gap: 10px;\n}\n\n.upgrade-item.maxed { border-color: var(--ui-dim); }\n\n.upgrade-info { text-align: left; }\n\n.upgrade-name {\n    font-size: 14px;\n    font-weight: 700;\n}\n\n.upgrade-lvl {\n    font-size: 11px;\n    color: #7c8391;\n    margin-top: 2px;\n}\n\n.upgrade-effect { color: var(--ui); }\n\n.btn-buy {\n    min-width: 76px;\n    transition: filter 0.2s, opacity 0.2s;\n}\n\n.btn-buy.locked {\n    filter: grayscale(0.85);\n    opacity: 0.45;\n}\n\n.btn-buy.maxed {\n    background: none;\n    border: 1px solid var(--ui-dim);\n    color: var(--ui);\n    box-shadow: none;\n    cursor: default;\n}\n\n@keyframes shakeX {\n    0%, 100% { transform: translateX(0); }\n    20% { transform: translateX(-6px); }\n    40% { transform: translateX(6px); }\n    60% { transform: translateX(-4px); }\n    80% { transform: translateX(4px); }\n}\n\n.shake { animation: shakeX 0.35s; }\n\n.record-badge {\n    background: linear-gradient(45deg, #ffaa00, #ffee00);\n    color: #201500;\n    font-weight: 900;\n    letter-spacing: 2px;\n    padding: 7px 20px;\n    border-radius: 20px;\n    margin-bottom: 14px;\n    animation: popIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n\n.go-score {\n    font-size: 44px;\n    font-weight: 900;\n    color: var(--ui);\n    line-height: 1;\n    font-variant-numeric: tabular-nums;\n}\n\n.go-sub {\n    font-size: 12px;\n    color: #7c8391;\n    margin-top: 6px;\n}\n\n.go-grid {\n    display: flex;\n    gap: 22px;\n    justify-content: center;\n    margin: 18px 0 4px;\n    font-size: 13px;\n    color: #cfd4dc;\n}\n\n.go-grid b {\n    display: block;\n    font-size: 17px;\n    color: #fff;\n    margin-bottom: 2px;\n}\n\n.hint {\n    font-size: 12px;\n    color: #656b78;\n    line-height: 1.7;\n    margin-top: 16px;\n}\n\n#secret-msg {\n    font-size: 12px;\n    min-height: 16px;\n    margin-top: 8px;\n}\n\n/*------ V\u00ddCVIK ------*/\n.tut-box {\n    position: absolute;\n    bottom: calc(24px + env(safe-area-inset-bottom, 0px));\n    left: 50%;\n    transform: translateX(-50%);\n    width: 90%;\n    max-width: 400px;\n    background: var(--panel);\n    border: 2px solid var(--ui);\n    border-radius: 16px;\n    padding: 16px;\n    color: #fff;\n    font-size: 14px;\n    line-height: 1.5;\n    z-index: 30;\n    box-shadow: 0 0 28px rgba(124, 58, 237, 0.28);\n    text-align: center;\n}\n\n.tut-step {\n    font-size: 11px;\n    color: var(--ui-dim);\n    letter-spacing: 2px;\n    margin-bottom: 6px;\n}\n\n.tut-skip {\n    background: none;\n    border: none;\n    color: #6c7280;\n    font-size: 12px;\n    text-decoration: underline;\n    cursor: pointer;\n    margin-top: 12px;\n}\n\n.glow-highlight {\n    box-shadow: 0 0 20px 8px var(--ui) !important;\n    border-color: #fff !important;\n    z-index: 100;\n    animation: pulseGlow 1s infinite alternate;\n}\n\n@keyframes pulseGlow {\n    from { box-shadow: 0 0 14px 4px var(--ui); }\n    to { box-shadow: 0 0 26px 13px var(--ui); }\n}\n\n#tut-focus-circle {\n    position: absolute;\n    border: 3px solid var(--ui);\n    border-radius: 50%;\n    pointer-events: none;\n    opacity: 0;\n    box-shadow: 0 0 20px var(--ui);\n    transition: opacity 0.3s;\n    z-index: 15;\n}\n\n#tut-focus-circle.show {\n    opacity: 1;\n    animation: pulseGlow 1s infinite alternate;\n}\n\n@media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n        animation-duration: 0.01ms !important;\n        animation-iteration-count: 1 !important;\n        transition-duration: 0.01ms !important;\n    }\n}\n\n/*------ RE\u017dIMY (v5) ------*/\n#hud-timer, #hud-streak { font-variant-numeric: tabular-nums; }\n#hud-timer.hidden, #hud-streak.hidden { display: none; }\n\n.btn-ghost {\n    background: none;\n    border: 1px solid var(--ui-dim);\n    color: var(--ui);\n    box-shadow: none;\n}\n\n.mode-grid {\n    width: 100%;\n    max-width: 350px;\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 9px;\n    margin: 4px 0 14px;\n}\n\n.mode-card {\n    background: var(--panel);\n    border: 1px solid var(--line);\n    border-radius: 14px;\n    padding: 13px 10px;\n    color: #fff;\n    text-align: left;\n    cursor: pointer;\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n    transition: transform 0.1s, border-color 0.2s;\n}\n\n.mode-card:active { transform: scale(0.96); }\n\n.mode-card .mode-icon { font-size: 19px; }\n.mode-card .mode-name { font-size: 14px; font-weight: 800; margin-top: 2px; }\n.mode-card .mode-desc { font-size: 11px; color: #8992a3; line-height: 1.35; min-height: 28px; }\n.mode-card .mode-rec { font-size: 11px; color: var(--ui); margin-top: 5px; font-variant-numeric: tabular-nums; }\n\n.mode-card.hard { border-color: rgba(255, 136, 0, 0.4); }\n.mode-card.hard .mode-rec { color: #ff9500; }\n.mode-card.blitz { border-color: rgba(255, 196, 0, 0.4); }\n.mode-card.blitz .mode-rec { color: var(--gold); }\n.mode-card.rush { border-color: rgba(255, 0, 204, 0.4); }\n.mode-card.rush .mode-rec { color: #ff5fe0; }\n.mode-card.zen { border-color: rgba(140, 200, 255, 0.4); }\n.mode-card.zen .mode-rec { color: #8cc8ff; }\n.mode-card.daily { border-color: rgba(140, 255, 180, 0.4); }\n.mode-card.daily .mode-rec { color: #8cffb4; }\n\n/*------ \u00daSP\u011aCHY - TOASTY ------*/\n#achv-toast-layer {\n    position: absolute;\n    top: calc(96px + env(safe-area-inset-top, 0px));\n    left: 50%;\n    transform: translateX(-50%);\n    z-index: 40;\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    align-items: center;\n    pointer-events: none;\n}\n\n.achv-toast {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    background: rgba(10, 13, 26, 0.96);\n    border: 1px solid var(--gold);\n    border-radius: 12px;\n    padding: 9px 16px 9px 12px;\n    box-shadow: 0 0 22px rgba(255, 196, 0, 0.35);\n    opacity: 0;\n    transform: translateY(-10px) scale(0.94);\n    transition: opacity 0.25s, transform 0.25s;\n    white-space: nowrap;\n}\n\n.achv-toast.show { opacity: 1; transform: translateY(0) scale(1); }\n.achv-toast-icon { font-size: 20px; }\n.achv-toast-eyebrow { font-size: 10px; color: var(--gold); letter-spacing: 1px; }\n.achv-toast-name { font-size: 13px; font-weight: 700; color: #fff; }\n\n/*------ POSTUP A \u00daSP\u011aCHY ------*/\n.stats-grid {\n    width: 100%;\n    max-width: 350px;\n    display: grid;\n    grid-template-columns: 1fr 1fr 1fr;\n    gap: 8px;\n    margin-bottom: 16px;\n    font-size: 11px;\n    color: #cfd4dc;\n    text-align: left;\n}\n\n.stats-grid > div {\n    background: var(--panel);\n    border: 1px solid var(--line);\n    border-radius: 10px;\n    padding: 8px 9px;\n}\n\n.stats-grid b {\n    display: block;\n    font-size: 16px;\n    color: #fff;\n    margin-bottom: 1px;\n    font-variant-numeric: tabular-nums;\n}\n\n.ascend-box {\n    width: 100%;\n    max-width: 350px;\n    background: linear-gradient(160deg, rgba(255, 196, 0, 0.12), var(--panel));\n    border: 1px solid rgba(255, 196, 0, 0.4);\n    border-radius: 14px;\n    padding: 13px;\n    margin-bottom: 16px;\n    text-align: left;\n}\n\n.ascend-title {\n    font-size: 14px;\n    font-weight: 800;\n    color: var(--gold);\n    margin-bottom: 4px;\n}\n\n.ascend-desc {\n    font-size: 12px;\n    color: #b7bcc7;\n    line-height: 1.5;\n    margin-bottom: 10px;\n}\n\n#btn-ascend {\n    width: 100%;\n    max-width: none;\n    margin: 0;\n    background: linear-gradient(45deg, #ffaa00, #ffee00);\n    color: #201500;\n    box-shadow: 0 4px 16px rgba(255, 196, 0, 0.3);\n}\n\n#btn-ascend.locked {\n    background: none;\n    border: 1px solid var(--line);\n    color: #6c7280;\n    box-shadow: none;\n    cursor: default;\n}\n\n.relic-list, .achv-list {\n    width: 100%;\n    max-width: 350px;\n    margin-bottom: 16px;\n}\n\n.relic-item {\n    background: var(--panel);\n    border: 1px solid var(--line);\n    border-radius: 12px;\n    padding: 9px 12px;\n    margin-bottom: 7px;\n    text-align: left;\n}\n\n.relic-item.unlocked { border-color: var(--ui-dim); }\n.relic-item.locked { opacity: 0.55; }\n.relic-name { font-size: 13px; font-weight: 700; }\n.relic-desc { font-size: 11px; color: #8992a3; margin-top: 2px; }\n\n.prestige-list {\n    width: 100%;\n    max-width: 350px;\n    margin-bottom: 16px;\n}\n\n.prestige-item {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 10px;\n    background: var(--panel);\n    border: 1px solid rgba(185, 139, 255, 0.3);\n    border-radius: 12px;\n    padding: 9px 12px;\n    margin-bottom: 7px;\n    text-align: left;\n}\n\n.prestige-item.maxed { border-color: #b98bff; }\n.prestige-name { font-size: 13px; font-weight: 700; }\n.prestige-desc { font-size: 11px; color: #8992a3; margin-top: 2px; }\n.prestige-lvl { font-size: 10px; color: #b98bff; margin-top: 2px; }\n\n.btn-prestige {\n    min-width: 68px;\n    background: linear-gradient(45deg, #7a3fd6, #b98bff);\n    box-shadow: 0 4px 12px rgba(185, 139, 255, 0.28);\n}\n\n.btn-prestige.locked { filter: grayscale(0.85); opacity: 0.45; }\n.btn-prestige.maxed { background: none; border: 1px solid #b98bff; color: #b98bff; box-shadow: none; cursor: default; }\n\n.achv-item {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    background: var(--panel);\n    border: 1px solid var(--line);\n    border-radius: 12px;\n    padding: 9px 12px;\n    margin-bottom: 7px;\n    text-align: left;\n}\n\n.achv-item.unlocked { border-color: rgba(255, 196, 0, 0.4); }\n.achv-item.locked { opacity: 0.55; }\n.achv-icon { font-size: 18px; flex-shrink: 0; }\n.achv-body { flex: 1; min-width: 0; }\n.achv-name { font-size: 13px; font-weight: 700; }\n.achv-desc { font-size: 11px; color: #8992a3; margin-top: 2px; line-height: 1.4; }\n.achv-progress { font-size: 10px; color: var(--ui); margin-top: 3px; font-variant-numeric: tabular-nums; }\n.achv-reward { font-size: 12px; color: var(--gold); font-weight: 700; flex-shrink: 0; }\n</style>\n</head>\n<body>\n\n<div id=\"game-container\">\n    <a href=\"/app\" id=\"btn-back-to-jomarid\" onclick=\"if (window.parent !== window) { window.parent.postMessage({ source: 'jomarid-game', type: 'close' }, '*'); return false; }\" style=\"position:absolute; top:calc(10px + env(safe-area-inset-top,0px)); left:10px; z-index:200; color:var(--ui-dim); font-size:11px; letter-spacing:0.5px; text-decoration:none; background:rgba(5,5,15,0.65); padding:6px 10px; border-radius:8px; border:1px solid var(--line); backdrop-filter: blur(4px);\">\u2190 Jomarid Books</a>\n    <canvas id=\"gameCanvas\"></canvas>\n    <div id=\"tut-focus-circle\"></div>\n    <div id=\"event-text\"></div>\n    <div id=\"achv-toast-layer\"></div>\n\n    <div class=\"hud hidden\" id=\"hud\">\n        <div class=\"hud-top\">\n            <div class=\"hud-group\" id=\"hud-stats-group\">\n                <span id=\"hud-score\">0</span>\n                <span id=\"hud-coins\">0</span>\n                <span id=\"hud-combo\" class=\"hidden\">\u00d72</span>\n                <span id=\"hud-timer\" class=\"hidden\">3:00</span>\n                <span id=\"hud-streak\" class=\"hidden\">S\u00e9rie 0</span>\n            </div>\n            <div class=\"hud-buttons\">\n                <button class=\"icon-btn\" id=\"btn-sound\" title=\"Zvuk (M)\">\ud83d\udd0a</button>\n                <button class=\"icon-btn\" id=\"btn-pause\" title=\"Pauza (Esc)\">II</button>\n            </div>\n        </div>\n\n        <div class=\"hp-row\">\n            <div class=\"hp-track\">\n                <div class=\"hp-fill\" id=\"hp-fill\"></div>\n                <div class=\"hp-ticks\"></div>\n            </div>\n            <span class=\"hp-num\" id=\"hp-num\">100/100</span>\n        </div>\n\n        <div class=\"boss-bar hidden\" id=\"boss-bar\">\n            <div class=\"boss-head\">\n                <span id=\"boss-name\">STR\u00c1\u017dCE</span>\n                <span id=\"boss-phase\">f\u00e1ze 1/3</span>\n            </div>\n            <div class=\"boss-track\"><div class=\"boss-fill\" id=\"boss-fill\"></div></div>\n        </div>\n\n        <div class=\"powerup-timers\" id=\"powerup-timers\"></div>\n    </div>\n\n    <button id=\"btn-bomb\" class=\"hidden\" title=\"Bomba (B)\">\ud83d\udca3<span id=\"bomb-count\">0</span></button>\n\n    <div id=\"tut-layer\" class=\"hidden\">\n        <div class=\"tut-box\" id=\"tut-box\">\n            <div class=\"tut-step\" id=\"tut-step\">V\u00ddCVIK</div>\n            <div id=\"tut-text\"></div>\n            <div style=\"margin-top: 14px; display: flex; justify-content: center; gap: 10px;\" id=\"tut-buttons\"></div>\n            <button class=\"tut-skip\" id=\"btn-tut-skip\">P\u0159esko\u010dit v\u00fdcvik</button>\n        </div>\n    </div>\n\n    <div id=\"menu-overlay\" class=\"overlay\">\n        <h1>OCHR\u00c1NCE</h1>\n        <p class=\"tagline\">Vesm\u00edrn\u00e1 ark\u00e1dov\u00e1 st\u0159\u00edle\u010dka</p>\n\n        <div class=\"stats-bar\">\n            <span id=\"menu-coins\" style=\"color: var(--gold);\">0 minc\u00ed</span>\n            <span id=\"menu-best\" style=\"color: var(--ui);\">Rekord 0</span>\n            <span id=\"menu-ascend\" class=\"hidden\" style=\"color: var(--gold);\">Vzestup 0</span>\n        </div>\n\n        <div class=\"mode-grid\">\n            <button class=\"mode-card\" id=\"btn-start-normal\">\n                <span class=\"mode-icon\">\ud83d\ude80</span>\n                <span class=\"mode-name\">Norm\u00e1ln\u00ed</span>\n                <span class=\"mode-desc\">Nekone\u010dn\u00e9 p\u0159e\u017eit\u00ed vlastn\u00edm tempem</span>\n                <span class=\"mode-rec\" id=\"rec-normal\">Rekord 0</span>\n            </button>\n            <button class=\"mode-card hard\" id=\"btn-start-hard\">\n                <span class=\"mode-icon\">\ud83d\udd25</span>\n                <span class=\"mode-name\">T\u011b\u017ek\u00e1</span>\n                <span class=\"mode-desc\">Rychlej\u0161\u00ed nep\u0159\u00e1tel\u00e9, v\u00edc bolesti</span>\n                <span class=\"mode-rec\" id=\"rec-hard\">Rekord 0</span>\n            </button>\n            <button class=\"mode-card blitz\" id=\"btn-start-blitz\">\n                <span class=\"mode-icon\">\u26a1</span>\n                <span class=\"mode-name\">Bleskov\u00e1 vlna</span>\n                <span class=\"mode-desc\">3 minuty na maxim\u00e1ln\u00ed sk\u00f3re</span>\n                <span class=\"mode-rec\" id=\"rec-blitz\">Rekord 0</span>\n            </button>\n            <button class=\"mode-card rush\" id=\"btn-start-rush\">\n                <span class=\"mode-icon\">\ud83d\udc79</span>\n                <span class=\"mode-name\">Boss Rush</span>\n                <span class=\"mode-desc\">Bossov\u00e9 jeden za druh\u00fdm, bez oddechu</span>\n                <span class=\"mode-rec\" id=\"rec-rush\">S\u00e9rie 0</span>\n            </button>\n            <button class=\"mode-card zen hidden\" id=\"btn-start-zen\">\n                <span class=\"mode-icon\">\ud83c\udf19</span>\n                <span class=\"mode-name\">Zen</span>\n                <span class=\"mode-desc\">Klidn\u00e1 nekone\u010dn\u00e1 hra, um\u0159\u00edt nejde</span>\n                <span class=\"mode-rec\" id=\"rec-zen\">Bez tlaku</span>\n            </button>\n            <button class=\"mode-card daily hidden\" id=\"btn-start-daily\">\n                <span class=\"mode-icon\">\ud83d\udcc5</span>\n                <span class=\"mode-name\">Denn\u00ed v\u00fdzva</span>\n                <span class=\"mode-desc\" id=\"daily-desc\">Dne\u0161n\u00ed modifik\u00e1tor</span>\n                <span class=\"mode-rec\" id=\"rec-daily\">Rekord 0</span>\n            </button>\n        </div>\n\n        <button class=\"btn btn-ghost btn-small\" id=\"btn-open-stats\" style=\"margin-bottom: 14px;\">Postup a \u00fasp\u011bchy</button>\n\n        <div class=\"section-label\">Trval\u00e1 vylep\u0161en\u00ed lodi</div>\n        <div class=\"upgrades-container\" id=\"menu-shop\"></div>\n\n        <button class=\"btn btn-danger\" id=\"btn-reset\" style=\"opacity: 0.6; font-size: 12px; padding: 8px; width: auto;\">Smazat postup</button>\n\n        <div style=\"margin-top: 14px; display: flex; gap: 6px; justify-content: center; align-items: center;\">\n            <input type=\"text\" id=\"secret-input\" placeholder=\"Tajn\u00fd k\u00f3d\" autocomplete=\"off\" style=\"padding: 8px 12px; border-radius: 15px; border: 1px solid var(--ui-dim); background: rgba(0,0,0,0.6); color: #fff; width: 130px; text-align: center; font-size: 13px; outline: none;\">\n            <button class=\"btn btn-small\" id=\"btn-secret\" style=\"margin: 0; padding: 8px 14px;\">Aktivovat</button>\n        </div>\n        <div id=\"secret-msg\"></div>\n\n        <div class=\"hint\">\n            Po\u010d\u00edta\u010d: \u0161ipky, WASD nebo my\u0161. Esc pauza, B bomba, M zvuk.<br>\n            Mobil: t\u00e1hn\u011bte prstem, bomba tla\u010d\u00edtkem vpravo dole.\n        </div>\n    </div>\n\n    <div id=\"stats-overlay\" class=\"overlay hidden\">\n        <h1 style=\"font-size: 26px;\">POSTUP</h1>\n        <p class=\"tagline\">V\u0161e, co jsi za dobu hran\u00ed dok\u00e1zal</p>\n\n        <div class=\"stats-grid\" id=\"lifetime-stats\"></div>\n\n        <div class=\"ascend-box\" id=\"ascend-box\">\n            <div class=\"ascend-title\">Vzestup <span id=\"ascend-level\">0</span> \u00b7 <span id=\"stardust-count\" style=\"color: #b98bff;\">0 \u2726 prachu</span></div>\n            <div class=\"ascend-desc\" id=\"ascend-desc\">Vylep\u0161i v\u0161ech osm kategori\u00ed na maximum, abys mohl vzestoupit.</div>\n            <button class=\"btn btn-small\" id=\"btn-ascend\" disabled>Vzestoupit</button>\n        </div>\n\n        <div class=\"section-label\">Strom Vzestupu (za \u2726 hv\u011bzdn\u00fd prach)</div>\n        <div class=\"prestige-list\" id=\"prestige-list\"></div>\n\n        <div class=\"section-label\">Relikvie</div>\n        <div class=\"relic-list\" id=\"relic-list\"></div>\n\n        <div class=\"section-label\">\u00dasp\u011bchy</div>\n        <div class=\"achv-list\" id=\"achv-list\"></div>\n\n        <button class=\"btn\" id=\"btn-close-stats\">Zp\u011bt do menu</button>\n    </div>\n\n    <div id=\"pause-overlay\" class=\"overlay hidden\">\n        <h1>PAUZA</h1>\n\n        <div class=\"stats-bar\">\n            <span id=\"pause-coins\" style=\"color: var(--gold);\">0 minc\u00ed</span>\n            <span id=\"pause-score\" style=\"color: var(--ui);\">Sk\u00f3re 0</span>\n        </div>\n\n        <button class=\"btn\" id=\"btn-resume\">Pokra\u010dovat</button>\n\n        <div class=\"section-label\">Vylep\u0161en\u00ed se projev\u00ed okam\u017eit\u011b</div>\n        <div class=\"upgrades-container\" id=\"pause-shop\"></div>\n\n        <button class=\"btn btn-danger\" id=\"btn-quit-pause\">Opustit hru</button>\n    </div>\n\n    <div id=\"gameover-overlay\" class=\"overlay hidden\">\n        <h2 id=\"go-heading\">LO\u010e ZNI\u010cENA</h2>\n        <div id=\"go-record\" class=\"record-badge hidden\">Nov\u00fd rekord</div>\n        <div class=\"section-label\" id=\"go-metric-label\" style=\"text-align: center; max-width: none;\">SK\u00d3RE</div>\n        <div class=\"go-score\" id=\"go-score\">0</div>\n        <div class=\"go-sub\" id=\"go-sub\">Rekord 0</div>\n        <div class=\"go-grid\" id=\"go-grid\"></div>\n        <button class=\"btn\" id=\"btn-restart\">Hr\u00e1t znovu</button>\n        <button class=\"btn btn-danger\" id=\"btn-quit-go\">Hlavn\u00ed menu</button>\n    </div>\n</div>\n\n<script>\n//======================================================================\n//  ULO\u017dEN\u00c1 DATA\n//======================================================================\n\nconst MAX_LVL = 20;\n\nconst Storage = {\n    key: 'space_shooter_v2_9',\n\n    defaults: {\n        coins: 0,\n        upgrades: {\n            fireRate: 1, hp: 1, damage: 1, bombs: 1,\n            tripleDuration: 1, shieldDuration: 1, rapidDuration: 1, healPower: 1\n        },\n        best: { normal: 0, hard: 0, blitz: 0, rush: 0, zen: 0 },\n        daily: { date: '', score: 0 },\n        muted: false,\n        tutorialDone: false,\n        ascension: 0,\n        stardust: 0,\n        cycleCoins: 0,\n        prestige: { hull: 0, aura: 0, magnet: 0, luck: 0, capital: 0, bomb: 0, zenUnlocked: false, dailyUnlocked: false },\n        achievements: {},\n        stats: {\n            totalKills: 0, totalBossKills: 0, totalCoinsEarned: 0, totalPlaytime: 0,\n            bestCombo: 0, runsPlayed: 0, bombsUsed: 0, noHitBosses: 0,\n            longestRun: 0, blitzClears: 0, bestRushStreak: 0\n        }\n    },\n\n    data: null,\n    dirty: false,\n    timer: null,\n\n    load() {\n        this.data = JSON.parse(JSON.stringify(this.defaults));\n\n        try {\n            const raw = localStorage.getItem(this.key);\n            if (raw) {\n                const parsed = JSON.parse(raw);\n                this.data = { ...this.data, ...parsed };\n                this.data.upgrades = { ...this.defaults.upgrades, ...(parsed.upgrades || {}) };\n                this.data.best = { ...this.defaults.best, ...(parsed.best || {}) };\n                this.data.stats = { ...this.defaults.stats, ...(parsed.stats || {}) };\n                this.data.prestige = { ...this.defaults.prestige, ...(parsed.prestige || {}) };\n                this.data.daily = (parsed.daily && typeof parsed.daily === 'object')\n                    ? { date: String(parsed.daily.date || ''), score: parsed.daily.score }\n                    : { ...this.defaults.daily };\n                // Nezn\u00e1m\u00e9 kl\u00ed\u010de v achievementech ne\u0161kod\u00ed - nikdy se pod ciz\u00edm id ne\u010dtou\n                this.data.achievements = (parsed.achievements && typeof parsed.achievements === 'object') ? { ...parsed.achievements } : {};\n            }\n        } catch (e) {\n            // Po\u0161kozen\u00e1 data nebo zak\u00e1zan\u00fd localStorage - hrajeme na v\u00fdchoz\u00edch hodnot\u00e1ch\n        }\n\n        if (!Number.isFinite(this.data.coins)) this.data.coins = 0;\n\n        if (!Number.isFinite(this.data.ascension) || this.data.ascension < 0) this.data.ascension = 0;\n        this.data.ascension = Math.floor(this.data.ascension);\n\n        if (!Number.isFinite(this.data.stardust) || this.data.stardust < 0) this.data.stardust = 0;\n        this.data.stardust = Math.floor(this.data.stardust);\n\n        if (!Number.isFinite(this.data.cycleCoins) || this.data.cycleCoins < 0) this.data.cycleCoins = 0;\n\n        for (const k in this.defaults.upgrades) {\n            const v = Math.floor(Number(this.data.upgrades[k]));\n            this.data.upgrades[k] = Number.isFinite(v) ? Math.min(MAX_LVL, Math.max(1, v)) : 1;\n        }\n\n        for (const k in this.defaults.best) {\n            if (!Number.isFinite(this.data.best[k])) this.data.best[k] = 0;\n        }\n\n        for (const k in this.defaults.stats) {\n            if (!Number.isFinite(this.data.stats[k]) || this.data.stats[k] < 0) this.data.stats[k] = 0;\n        }\n\n        for (const k in this.defaults.prestige) {\n            if (typeof this.defaults.prestige[k] === 'boolean') {\n                this.data.prestige[k] = !!this.data.prestige[k];\n            } else if (!Number.isFinite(this.data.prestige[k]) || this.data.prestige[k] < 0) {\n                this.data.prestige[k] = 0;\n            } else {\n                this.data.prestige[k] = Math.floor(this.data.prestige[k]);\n            }\n        }\n\n        if (!Number.isFinite(this.data.daily.score) || this.data.daily.score < 0) this.data.daily.score = 0;\n    },\n\n    save() {\n        this.dirty = false;\n        try {\n            localStorage.setItem(this.key, JSON.stringify(this.data));\n        } catch (e) {}\n    },\n\n    // Z\u00e1pis do localStorage je drah\u00fd - b\u011bhem boje jen ozna\u010d\u00edme zm\u011bnu a ulo\u017e\u00edme d\u00e1vkov\u011b\n    queueSave() {\n        this.dirty = true;\n        if (this.timer) return;\n\n        this.timer = setTimeout(() => {\n            this.timer = null;\n            if (this.dirty) this.save();\n        }, 1500);\n    },\n\n    flush() {\n        if (this.dirty) this.save();\n    },\n\n    wipe() {\n        this.data = JSON.parse(JSON.stringify(this.defaults));\n        this.save();\n    }\n};\n\nStorage.load();\nwindow.addEventListener('pagehide', () => Storage.flush());\n\n//======================================================================\n//  ZVUK\n//======================================================================\n\nclass SoundSystem {\n    constructor() {\n        this.ctx = null;\n        this.muted = false;\n        this.activeUntil = []; // \u010dasov\u00e1 raz\u00edtka konce ka\u017ed\u00e9ho zn\u011bj\u00edc\u00edho zvuku\n    }\n\n    init() {\n        try {\n            if (!this.ctx) this.ctx = new (window.AudioContext || window.webkitAudioContext)();\n            if (this.ctx.state === 'suspended') this.ctx.resume();\n        } catch (e) {}\n    }\n\n    setMuted(m) { this.muted = !!m; }\n\n    ready() {\n        if (!this.ctx || this.muted) return false;\n\n        // Po\u010det aktivn\u00edch hlas\u016f po\u010d\u00edt\u00e1me z \u010dasov\u00fdch raz\u00edtek, ne z setTimeout dekrement\u016f -\n        // ty se na zabackgroundovan\u00e9 kart\u011b zpo\u017e\u010fuj\u00ed a hra by tak mohla z\u016fstat trvale n\u011bm\u00e1\n        const now = Date.now();\n        if (this.activeUntil.length) {\n            this.activeUntil = this.activeUntil.filter(t => t > now);\n        }\n\n        // Strop hlas\u016f br\u00e1n\u00ed prask\u00e1n\u00ed, kdy\u017e vybuchne p\u016flka obrazovky nar\u00e1z\n        return this.activeUntil.length < 14;\n    }\n\n    track(duration) {\n        this.activeUntil.push(Date.now() + duration * 1000 + 60);\n    }\n\n    tone(freq, type, duration, vol, endFreq) {\n        if (!this.ready()) return;\n\n        const t = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n\n        osc.type = type;\n        osc.frequency.setValueAtTime(freq, t);\n        osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq === undefined ? freq / 2 : endFreq), t + duration);\n\n        gain.gain.setValueAtTime(vol, t);\n        gain.gain.exponentialRampToValueAtTime(0.008, t + duration);\n\n        osc.connect(gain);\n        gain.connect(this.ctx.destination);\n        osc.start(t);\n        osc.stop(t + duration);\n\n        this.track(duration);\n    }\n\n    // \u0160um d\u00e1 v\u00fdbuch\u016fm t\u011blo, kter\u00e9 samotn\u00fd oscil\u00e1tor ned\u00e1\n    noise(duration, vol, cutoff) {\n        if (!this.ready()) return;\n\n        const ctx = this.ctx;\n        const t = ctx.currentTime;\n        const len = Math.max(1, Math.floor(ctx.sampleRate * duration));\n        const buf = ctx.createBuffer(1, len, ctx.sampleRate);\n        const data = buf.getChannelData(0);\n\n        for (let i = 0; i < len; i++) {\n            data[i] = (Math.random() * 2 - 1) * (1 - i / len);\n        }\n\n        const src = ctx.createBufferSource();\n        src.buffer = buf;\n\n        const filter = ctx.createBiquadFilter();\n        filter.type = 'lowpass';\n        filter.frequency.setValueAtTime(cutoff, t);\n        filter.frequency.exponentialRampToValueAtTime(Math.max(120, cutoff * 0.25), t + duration);\n\n        const gain = ctx.createGain();\n        gain.gain.setValueAtTime(vol, t);\n        gain.gain.exponentialRampToValueAtTime(0.008, t + duration);\n\n        src.connect(filter);\n        filter.connect(gain);\n        gain.connect(ctx.destination);\n        src.start(t);\n\n        this.track(duration);\n    }\n\n    shoot() { this.tone(680, 'square', 0.06, 0.045, 420); }\n    enemyShoot() { this.tone(240, 'square', 0.09, 0.05, 150); }\n    hit() { this.tone(180, 'sawtooth', 0.1, 0.18, 70); }\n    heal() { this.tone(520, 'sine', 0.26, 0.18, 880); }\n    powerup() { this.tone(460, 'sine', 0.28, 0.2, 920); }\n    explosion() { this.noise(0.34, 0.26, 1400); this.tone(90, 'square', 0.22, 0.14, 40); }\n    bigExplosion() { this.noise(0.75, 0.38, 2200); this.tone(58, 'sawtooth', 0.6, 0.26, 26); }\n    bossSpawn() { this.tone(46, 'sawtooth', 1.1, 0.32, 120); }\n    telegraph() { this.tone(300, 'triangle', 0.2, 0.1, 620); }\n    beam() { this.noise(0.5, 0.2, 3600); this.tone(160, 'sawtooth', 0.5, 0.14, 420); }\n    bomb() { this.noise(1.0, 0.42, 3000); this.tone(70, 'sine', 0.8, 0.3, 30); }\n    combo(n) { this.tone(480 + n * 70, 'triangle', 0.1, 0.1, 760 + n * 70); }\n    buy() { this.tone(900, 'triangle', 0.15, 0.13, 1300); }\n    denied() { this.tone(150, 'square', 0.16, 0.1, 90); }\n    phase() { this.tone(120, 'sawtooth', 0.7, 0.24, 500); }\n}\n\nconst Sounds = new SoundSystem();\nSounds.setMuted(Storage.data.muted);\n\n// AudioContext sm\u00ed vzniknout a\u017e po prvn\u00ed interakci - jinak by desktop z\u016fstal n\u011bm\u00fd\n['pointerdown', 'keydown', 'click'].forEach(ev => {\n    window.addEventListener(ev, () => Sounds.init(), { passive: true });\n});\n\n//======================================================================\n//  POMOCN\u00c9 FUNKCE\n//======================================================================\n\nconst U = {\n    rand: (min, max) => Math.random() * (max - min) + min,\n    pick: arr => arr[Math.floor(Math.random() * arr.length)],\n    clamp: (v, lo, hi) => Math.max(lo, Math.min(hi, v)),\n    dist: (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1),\n    lerp: (a, b, t) => a + (b - a) * t,\n\n    // Kolize dvou kruh\u016f; r2 dovol\u00ed pou\u017e\u00edt men\u0161\u00ed z\u00e1sahov\u00fd polom\u011br, ne\u017e jak\u00fd je vid\u011bt\n    hit: (a, b, ar, br) => {\n        const ra = ar === undefined ? a.r : ar;\n        const rb = br === undefined ? b.r : br;\n        return U.dist(a.x, a.y, b.x, b.y) < ra + rb;\n    },\n\n    // Mezera po tis\u00edc\u00edch je \u010diteln\u011bj\u0161\u00ed ne\u017e \u0161\u0148\u016fra \u010d\u00edslic\n    num: n => String(Math.round(n)).replace(/\\B(?=(\\d{3})+(?!\\d))/g, '\\u202f')\n};\n\n//======================================================================\n//  \u010c\u00c1STICE A TEXTY\n//======================================================================\n\nclass Particle {\n    constructor(x, y, color, speed, size, decay, angle) {\n        this.x = x;\n        this.y = y;\n        this.color = color;\n\n        const a = angle === undefined ? U.rand(0, Math.PI * 2) : angle;\n        this.vx = Math.cos(a) * speed;\n        this.vy = Math.sin(a) * speed;\n\n        this.size = size;\n        this.life = 1.0;\n        this.decay = decay;\n    }\n\n    update(dt) {\n        const f = dt / 16;\n        this.x += this.vx * f;\n        this.y += this.vy * f;\n        this.vx *= 0.97;\n        this.vy *= 0.97;\n        this.life -= this.decay * f;\n    }\n\n    draw(ctx) {\n        ctx.globalAlpha = Math.max(0, this.life);\n        ctx.fillStyle = this.color;\n        ctx.beginPath();\n        ctx.arc(this.x, this.y, this.size * Math.max(0.2, this.life), 0, Math.PI * 2);\n        ctx.fill();\n        ctx.globalAlpha = 1;\n    }\n}\n\nclass FloatingText {\n    constructor(x, y, text, color, size) {\n        this.x = x;\n        this.y = y;\n        this.text = text;\n        this.color = color;\n        this.size = size || 14;\n        this.life = 1.0;\n        this.decay = 0.022;\n    }\n\n    update(dt) {\n        const f = dt / 16;\n        this.y -= 0.7 * f;\n        this.life -= this.decay * f;\n    }\n\n    draw(ctx) {\n        ctx.globalAlpha = Math.max(0, this.life);\n        ctx.fillStyle = this.color;\n        ctx.font = `900 ${this.size}px 'Segoe UI', sans-serif`;\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText(this.text, this.x, this.y);\n        ctx.globalAlpha = 1;\n    }\n}\n\n//======================================================================\n//  ST\u0158ELY\n//======================================================================\n\nclass Bullet {\n    constructor(x, y, vx, vy, dmg, color, isEnemy, r) {\n        this.x = x;\n        this.y = y;\n        this.vx = vx;\n        this.vy = vy;\n        this.dmg = dmg;\n        this.color = color;\n        this.isEnemy = !!isEnemy;\n        this.r = r || (isEnemy ? 6 : 4);\n        this.life = 6000;\n    }\n\n    update(dt) {\n        const f = dt / 16;\n        this.x += this.vx * f;\n        this.y += this.vy * f;\n        this.life -= dt;\n    }\n\n    draw(ctx) {\n        ctx.shadowColor = this.color;\n        ctx.shadowBlur = 10;\n\n        if (this.isEnemy) {\n            ctx.fillStyle = this.color;\n            ctx.beginPath();\n            ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);\n            ctx.fill();\n\n            // Sv\u011btl\u00e9 j\u00e1dro odli\u0161\u00ed st\u0159elu od pozad\u00ed i p\u0159es v\u00fdbuchy\n            ctx.shadowBlur = 0;\n            ctx.fillStyle = 'rgba(255,255,255,0.85)';\n            ctx.beginPath();\n            ctx.arc(this.x, this.y, this.r * 0.42, 0, Math.PI * 2);\n            ctx.fill();\n        } else {\n            ctx.fillStyle = this.color;\n            ctx.beginPath();\n            ctx.ellipse(this.x, this.y, this.r, this.r * 2.1, 0, 0, Math.PI * 2);\n            ctx.fill();\n        }\n\n        ctx.shadowBlur = 0;\n    }\n}\n\n// Paprsek bosse: nejd\u0159\u00edv varovn\u00e1 linka, teprve potom \u0161kod\u00ed\nclass Beam {\n    constructor(boss, width, warnTime, fireTime, sweep) {\n        this.boss = boss;\n        this.x = boss.x;\n        this.w = width;\n        this.warn = warnTime;\n        this.fire = fireTime;\n        this.sweep = sweep || 0;\n        this.t = 0;\n        this.dead = false;\n    }\n\n    get firing() { return this.t >= this.warn && this.t < this.warn + this.fire; }\n\n    update(dt, game) {\n        this.t += dt;\n\n        if (this.t < this.warn) {\n            this.x = this.boss && !this.boss.dead ? this.boss.x : this.x;\n        } else {\n            this.x += this.sweep * (dt / 16);\n            this.x = U.clamp(this.x, 20, game.width - 20);\n        }\n\n        if (this.t >= this.warn + this.fire) this.dead = true;\n    }\n\n    draw(ctx, game) {\n        const top = this.boss ? this.boss.y : 0;\n\n        if (this.t < this.warn) {\n            const blink = 0.25 + Math.abs(Math.sin(this.t * 0.02)) * 0.5;\n            ctx.globalAlpha = blink;\n            ctx.strokeStyle = '#ff3366';\n            ctx.lineWidth = 2;\n            ctx.setLineDash([9, 7]);\n            ctx.beginPath();\n            ctx.moveTo(this.x, top);\n            ctx.lineTo(this.x, game.height);\n            ctx.stroke();\n            ctx.setLineDash([]);\n            ctx.globalAlpha = 1;\n            return;\n        }\n\n        const fade = U.clamp((this.warn + this.fire - this.t) / 180, 0, 1);\n        const w = this.w * fade;\n        const grad = ctx.createLinearGradient(this.x - w, 0, this.x + w, 0);\n\n        grad.addColorStop(0, 'rgba(255,0,90,0)');\n        grad.addColorStop(0.5, 'rgba(255,90,140,0.85)');\n        grad.addColorStop(1, 'rgba(255,0,90,0)');\n\n        ctx.fillStyle = grad;\n        ctx.fillRect(this.x - w, top, w * 2, game.height - top);\n\n        ctx.fillStyle = 'rgba(255,255,255,0.9)';\n        ctx.fillRect(this.x - w * 0.22, top, w * 0.44, game.height - top);\n    }\n}\n\n// Rozp\u00ednaj\u00edc\u00ed se tlakov\u00e1 vlna - d\u00e1 se obej\u00edt vzd\u00e1lenost\u00ed, ne jen \u00fahybem do strany\nclass Shockwave {\n    constructor(x, y, color, delay) {\n        this.x = x;\n        this.y = y;\n        this.color = color;\n        this.r = 0;\n        this.prevR = 0;\n        this.speed = 4.2;\n        this.band = 26;\n        this.delay = delay || 0;\n        this.t = 0;\n        this.hit = false;\n        this.dead = false;\n        this.maxR = 900;\n    }\n\n    get active() { return this.t >= this.delay; }\n\n    update(dt) {\n        this.t += dt;\n        if (!this.active) return;\n\n        this.prevR = this.r;\n        this.r += this.speed * (dt / 16);\n        if (this.r > this.maxR) this.dead = true;\n    }\n\n    draw(ctx) {\n        if (!this.active) return;\n\n        const alpha = U.clamp(1 - this.r / this.maxR, 0, 1) * 0.8;\n        if (alpha <= 0) return;\n\n        ctx.globalAlpha = alpha;\n        ctx.strokeStyle = this.color;\n        ctx.lineWidth = this.band;\n        ctx.beginPath();\n        ctx.arc(this.x, this.y, Math.max(0, this.r), 0, Math.PI * 2);\n        ctx.stroke();\n\n        ctx.globalAlpha = alpha * 0.6;\n        ctx.lineWidth = 2;\n        ctx.strokeStyle = '#ffffff';\n        ctx.stroke();\n        ctx.globalAlpha = 1;\n    }\n}\n\n//======================================================================\n//  POWER-UPY\n//======================================================================\n\nconst POWERUP_STYLE = {\n    triple: { color: '#ffcc00', icon: '\u26a1' },\n    shield: { color: '#00aaff', icon: '\ud83d\udee1\ufe0f' },\n    heal:   { color: '#00ff66', icon: '\u2764\ufe0f' },\n    rapid:  { color: '#ff4400', icon: '\ud83d\udd25' },\n    coin:   { color: '#ffd700', icon: '\ud83e\ude99' }\n};\n\nclass Powerup {\n    constructor(x, y, type) {\n        this.x = x;\n        this.y = y;\n        this.r = 14;\n        this.vy = 2.2;\n        this.vx = 0;\n        this.t = 0;\n        this.type = type;\n\n        const s = POWERUP_STYLE[type] || POWERUP_STYLE.triple;\n        this.color = s.color;\n        this.icon = s.icon;\n    }\n\n    update(dt, game) {\n        const f = dt / 16;\n        this.t += dt;\n\n        // Kr\u00e1tk\u00fd dolet k lodi, aby se odm\u011bna neztr\u00e1cela t\u011bsn\u011b vedle - Magnetick\u00e9\n        // j\u00e1dro ze stromu Vzestupu tento dosah trvale roz\u0161i\u0159uje\n        const p = game.player;\n        const d = U.dist(this.x, this.y, p.x, p.y);\n        const range = 130 * (p.magnetMul || 1);\n\n        if (d < range) {\n            const pull = (1 - d / range) * 2.6;\n            this.x += ((p.x - this.x) / d) * pull * f;\n            this.y += ((p.y - this.y) / d) * pull * f;\n        }\n\n        this.y += this.vy * f;\n    }\n\n    draw(ctx) {\n        const pulse = 1 + Math.sin(this.t * 0.007) * 0.09;\n\n        ctx.save();\n        ctx.translate(this.x, this.y);\n        ctx.scale(pulse, pulse);\n\n        ctx.fillStyle = this.color;\n        ctx.shadowColor = this.color;\n        ctx.shadowBlur = 14;\n        ctx.beginPath();\n        ctx.arc(0, 0, this.r, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.shadowBlur = 0;\n\n        ctx.fillStyle = '#000';\n        ctx.font = '14px sans-serif';\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText(this.icon, 0, 0);\n\n        ctx.restore();\n    }\n}\n\n//======================================================================\n//  HR\u00c1\u010c\n//======================================================================\n\nclass Player {\n    constructor(gw, gh) {\n        this.gw = gw;\n        this.gh = gh;\n\n        this.r = 17;\n        this.hitR = 7;          // Z\u00e1sahov\u00e1 z\u00f3na je men\u0161\u00ed ne\u017e lo\u010f - klasika \u017e\u00e1nru, jinak je hra nef\u00e9r\n        this.x = gw / 2;\n        this.y = gh - 90;\n        this.prevX = this.x;\n        this.tilt = 0;\n\n        this.applyStats();\n        this.hp = this.maxHp;\n        this.bombs = this.maxBombs;\n\n        this.fireTimer = 0;\n        this.tripleShotTimer = 0;\n        this.shieldTimer = 0;\n        this.rapidTimer = 0;\n        this.invulnTimer = 0;\n        this.trailTimer = 0;\n\n        this.speed = 5.8;\n    }\n\n    applyStats() {\n        const u = Storage.data.upgrades;\n\n        // Vzestup n\u00e1sob\u00ed z\u00e1klad natrvalo, relikvie se odemykaj\u00ed hran\u00edm, ne pen\u011bzi\n        const asc = Storage.data.ascension || 0;\n        // Bonus siln\u011b sl\u00e1bne po 15. vzestupu - hodn\u011b vzestoupen\u00fd hr\u00e1\u010d nem\u00e1 b\u00fdt rychlej\u0161\u00ed,\n        // jen odoln\u011bj\u0161\u00ed. Skute\u010dn\u00e1 odm\u011bna za dal\u0161\u00ed vzestupy jde do Hv\u011bzdn\u00e9ho prachu.\n        const ascMul = 1 + Math.min(asc, 15) * 0.025 + Math.max(0, asc - 15) * 0.006;\n        const relicDmg = Achv.hasRelic('barrel') ? 1.2 : 1;\n        const relicHp = Achv.hasRelic('plating') ? 1.15 : 1;\n        const relicFire = Achv.hasRelic('quickhand') ? 0.85 : 1;\n        const relicBombs = Achv.hasRelic('bombs') ? 1 : 0;\n\n        // Strom Vzestupu: ploch\u00e9/stropovan\u00e9 bonusy, nic co by hru zrychlovalo s dal\u0161\u00edmi vzestupy\n        const hullMul = 1 + prestigeBonus('hull', 0.02);\n        const auraMul = 1 + prestigeBonus('aura', 0.04);\n        this.magnetMul = 1 + prestigeBonus('magnet', 0.1);\n        const prestigeBombs = prestigeLevel('bomb');\n\n        this.maxHp = Math.round((80 + (u.hp || 1) * 20) * ascMul * relicHp * hullMul);\n        this.dmg = Math.round(((u.damage || 1) + 1) * ascMul * relicDmg);\n        // M\u00edrn\u011bj\u0161\u00ed k\u0159ivka: d\u0159\u00edv se palba vysytila kolem 9. \u00farovn\u011b a d\u00e1l u\u017e nic ned\u011blala\n        this.baseFireRate = Math.max(90, Math.round(Math.max(120, 430 - (u.fireRate || 1) * 16) * relicFire));\n\n        // \u0160t\u00edt je pln\u00e1 nezranitelnost, proto roste nejpomaleji ze v\u0161ech t\u0159\u00ed\n        this.tripleTime = Math.round((7000 + ((u.tripleDuration || 1) - 1) * 550) * auraMul);\n        this.shieldTime = Math.round((5000 + ((u.shieldDuration || 1) - 1) * 450) * auraMul);\n        this.rapidTime = Math.round((6000 + ((u.rapidDuration || 1) - 1) * 500) * auraMul);\n        this.healAmount = 25 + (((u.healPower || 1) - 1) * 10);\n        this.maxBombs = Math.min(7, 1 + Math.floor(((u.bombs || 1) - 1) / 3) + relicBombs + prestigeBombs);\n    }\n\n    update(dt, input, game) {\n        const f = dt / 16;\n        this.prevX = this.x;\n\n        let vx = 0, vy = 0;\n        if (input.keys['ArrowLeft'] || input.keys['KeyA']) vx = -this.speed;\n        if (input.keys['ArrowRight'] || input.keys['KeyD']) vx = this.speed;\n        if (input.keys['ArrowUp'] || input.keys['KeyW']) vy = -this.speed;\n        if (input.keys['ArrowDown'] || input.keys['KeyS']) vy = this.speed;\n\n        // \u0158\u00edd\u00ed ten ovlada\u010d, kter\u00fd hr\u00e1\u010d pou\u017eil naposledy\n        if (input.mode === 'pointer' && input.pointerActive) {\n            this.x = U.lerp(this.x, input.pointerTarget.x, Math.min(1, 0.55 * f));\n            this.y = U.lerp(this.y, input.pointerTarget.y, Math.min(1, 0.55 * f));\n        } else {\n            this.x += vx * f;\n            this.y += vy * f;\n        }\n\n        this.x = U.clamp(this.x, this.r, this.gw - this.r);\n        this.y = U.clamp(this.y, this.r, this.gh - this.r);\n\n        // N\u00e1klon podle skute\u010dn\u00e9ho pohybu funguje pro prst i kl\u00e1vesnici stejn\u011b\n        this.tilt = U.lerp(this.tilt, U.clamp((this.x - this.prevX) * 0.05, -0.42, 0.42), 0.2);\n\n        if (this.tripleShotTimer > 0) this.tripleShotTimer -= dt;\n        if (this.shieldTimer > 0) this.shieldTimer -= dt;\n        if (this.rapidTimer > 0) this.rapidTimer -= dt;\n        if (this.invulnTimer > 0) this.invulnTimer -= dt;\n\n        this.trailTimer -= dt;\n        if (this.trailTimer <= 0) {\n            this.trailTimer = 45;\n            game.particles.push(new Particle(\n                this.x + U.rand(-3, 3), this.y + 16,\n                this.rapidTimer > 0 ? '#ff6622' : '#00a8ff',\n                U.rand(0.3, 0.9), U.rand(1.5, 3), 0.07, Math.PI / 2\n            ));\n        }\n\n        const rate = this.rapidTimer > 0 ? Math.max(60, this.baseFireRate * 0.36) : this.baseFireRate;\n        this.fireTimer += dt;\n\n        if (this.fireTimer >= rate && !game.holdFire) {\n            this.fireTimer = 0;\n            this.shoot(game);\n        }\n    }\n\n    shoot(game) {\n        Sounds.shoot();\n\n        const y = this.y - 18;\n        const v = -14.5;\n\n        if (this.tripleShotTimer > 0) {\n            game.bullets.push(new Bullet(this.x, y, 0, v, this.dmg, '#00f0ff'));\n            game.bullets.push(new Bullet(this.x - 11, y + 6, -2.6, v * 0.92, this.dmg, '#00f0ff'));\n            game.bullets.push(new Bullet(this.x + 11, y + 6, 2.6, v * 0.92, this.dmg, '#00f0ff'));\n        } else {\n            game.bullets.push(new Bullet(this.x - 6, y, 0, v, this.dmg, '#00f0ff'));\n            game.bullets.push(new Bullet(this.x + 6, y, 0, v, this.dmg, '#00f0ff'));\n        }\n\n        game.particles.push(new Particle(this.x, y, '#bff8ff', 0.6, 2.2, 0.16));\n    }\n\n    takeDamage(amount, iframes) {\n        if (this.shieldTimer > 0 || this.invulnTimer > 0) return false;\n\n        this.hp -= amount;\n        this.invulnTimer = iframes === undefined ? 400 : iframes;\n        Sounds.hit();\n\n        return this.hp <= 0;\n    }\n\n    heal(amount) {\n        this.hp = Math.min(this.maxHp, this.hp + amount);\n        Sounds.heal();\n    }\n\n    draw(ctx) {\n        ctx.save();\n        ctx.translate(this.x, this.y);\n        ctx.rotate(this.tilt);\n\n        if (this.invulnTimer > 0 && this.shieldTimer <= 0) {\n            ctx.globalAlpha = (Math.floor(Date.now() / 70) % 2) ? 0.3 : 1;\n        }\n\n        if (this.shieldTimer > 0) {\n            const pulse = 0.28 + Math.sin(Date.now() / 110) * 0.09;\n            ctx.beginPath();\n            ctx.arc(0, 0, this.r + 11, 0, Math.PI * 2);\n            ctx.fillStyle = `rgba(0, 170, 255, ${pulse})`;\n            ctx.fill();\n            ctx.strokeStyle = '#00aaff';\n            ctx.lineWidth = 2;\n            ctx.stroke();\n\n            // Posledn\u00ed vte\u0159ina \u0161t\u00edtu blik\u00e1, a\u0165 konec nep\u0159ekvap\u00ed\n            if (this.shieldTimer < 1200 && Math.floor(this.shieldTimer / 120) % 2) {\n                ctx.strokeStyle = '#fff';\n                ctx.stroke();\n            }\n        }\n\n        ctx.fillStyle = this.rapidTimer > 0 ? '#ff3300' : (Math.random() > 0.5 ? '#ff8800' : '#ffcc00');\n        ctx.beginPath();\n        ctx.moveTo(-5, 11);\n        ctx.lineTo(5, 11);\n        ctx.lineTo(0, 20 + Math.random() * 9);\n        ctx.closePath();\n        ctx.fill();\n\n        ctx.fillStyle = '#00f0ff';\n        ctx.shadowColor = '#00f0ff';\n        ctx.shadowBlur = 12;\n        ctx.beginPath();\n        ctx.moveTo(0, -this.r);\n        ctx.lineTo(-this.r, this.r - 5);\n        ctx.lineTo(0, this.r - 10);\n        ctx.lineTo(this.r, this.r - 5);\n        ctx.closePath();\n        ctx.fill();\n\n        ctx.shadowBlur = 0;\n        ctx.fillStyle = '#d8fbff';\n        ctx.beginPath();\n        ctx.arc(0, -2, 3.2, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.restore();\n    }\n}\n\n//======================================================================\n//  B\u011a\u017dN\u00cd NEP\u0158\u00c1TEL\u00c9\n//======================================================================\n\nconst ENEMY_TYPES = {\n    basic:     { r: 17, hp: 2,  speed: 2.4, color: '#ff0055', score: 3,  coins: 6 },\n    fast:      { r: 12, hp: 1,  speed: 4.4, color: '#ff00ff', score: 5,  coins: 6 },\n    tank:      { r: 25, hp: 7,  speed: 1.15, color: '#ff8800', score: 10, coins: 18 },\n    destroyer: { r: 30, hp: 22, speed: 0.72, color: '#aa0000', score: 24, coins: 48 },\n    asteroid:  { r: 30, hp: Infinity, speed: 4, color: '#6b6b74', score: 0, coins: 0 }\n};\n\nclass Enemy {\n    constructor(x, y, type, diffMult) {\n        const s = ENEMY_TYPES[type] || ENEMY_TYPES.basic;\n\n        this.x = x;\n        this.y = y;\n        this.type = type;\n        this.r = type === 'asteroid' ? U.rand(20, 38) : s.r;\n        this.maxHp = s.hp === Infinity ? Infinity : Math.max(1, Math.round(s.hp * diffMult));\n        this.hp = this.maxHp;\n        this.speed = type === 'asteroid' ? U.rand(3, 5.5) : s.speed;\n        this.color = s.color;\n        this.scoreVal = s.score;\n        this.coinAmt = s.coins;\n\n        this.vx = 0;\n        this.t = U.rand(0, 3000);\n        this.hitFlash = 0;\n        this.angle = 0;\n        this.rotSpeed = U.rand(-0.05, 0.05);\n        this.fireTimer = U.rand(900, 2200);\n        this.dead = false;\n    }\n\n    get indestructible() { return this.type === 'asteroid'; }\n\n    update(dt, game) {\n        const f = dt / 16;\n        this.t += dt;\n        if (this.hitFlash > 0) this.hitFlash -= dt;\n\n        switch (this.type) {\n            case 'asteroid':\n                this.y += this.speed * f;\n                this.angle += this.rotSpeed * f;\n                break;\n\n            case 'fast':\n                // Rychl\u00edci let\u00ed po nastaven\u00e9 dr\u00e1ze, tak\u017ee maj\u00ed sp\u00e1d i do stran\n                this.y += this.speed * f;\n                this.x += this.vx * f;\n                break;\n\n            case 'destroyer': {\n                this.y += this.speed * f;\n                this.fireTimer -= dt;\n\n                if (this.fireTimer <= 0 && this.y > 40 && this.y < game.height * 0.62) {\n                    this.fireTimer = U.rand(1500, 2400);\n                    this.shootAt(game, game.player, 4.6, 8);\n                }\n                break;\n            }\n\n            case 'tank':\n                this.y += this.speed * f;\n                this.x += Math.sin(this.t * 0.0016) * 0.5 * f;\n                break;\n\n            default:\n                this.y += this.speed * f;\n                this.x += Math.sin(this.t * 0.0026) * 0.9 * f;\n        }\n\n        this.x = U.clamp(this.x, -60, game.width + 60);\n    }\n\n    shootAt(game, target, speed, dmg) {\n        const a = Math.atan2(target.y - this.y, target.x - this.x);\n        game.bullets.push(new Bullet(this.x, this.y + 10, Math.cos(a) * speed, Math.sin(a) * speed, dmg, '#ff6600', true, 6));\n        game.particles.push(new Particle(this.x, this.y + 12, '#ffaa44', 1.2, 2.5, 0.12));\n        Sounds.enemyShoot();\n    }\n\n    draw(ctx) {\n        ctx.save();\n        ctx.translate(this.x, this.y);\n\n        const fill = this.hitFlash > 0 ? '#ffffff' : this.color;\n\n        if (this.type === 'asteroid') {\n            ctx.rotate(this.angle);\n            ctx.fillStyle = fill;\n            ctx.beginPath();\n            ctx.moveTo(-this.r * 0.8, -this.r * 0.5);\n            ctx.lineTo(0, -this.r);\n            ctx.lineTo(this.r * 0.9, -this.r * 0.4);\n            ctx.lineTo(this.r, this.r * 0.6);\n            ctx.lineTo(this.r * 0.2, this.r);\n            ctx.lineTo(-this.r * 0.7, this.r * 0.8);\n            ctx.closePath();\n            ctx.fill();\n\n            ctx.fillStyle = 'rgba(0,0,0,0.3)';\n            ctx.beginPath();\n            ctx.arc(-this.r * 0.2, -this.r * 0.1, this.r * 0.26, 0, Math.PI * 2);\n            ctx.fill();\n\n            ctx.restore();\n            return;\n        }\n\n        ctx.shadowColor = this.color;\n        ctx.shadowBlur = 11;\n        ctx.fillStyle = fill;\n\n        if (this.type === 'destroyer') {\n            ctx.beginPath();\n            ctx.moveTo(-this.r, -this.r * 0.45);\n            ctx.lineTo(this.r, -this.r * 0.45);\n            ctx.lineTo(this.r * 0.6, this.r * 0.6);\n            ctx.lineTo(-this.r * 0.6, this.r * 0.6);\n            ctx.closePath();\n            ctx.fill();\n\n            ctx.shadowBlur = 0;\n            ctx.fillStyle = '#ffcc66';\n            ctx.fillRect(-4, this.r * 0.4, 8, 7);\n        } else if (this.type === 'tank') {\n            ctx.beginPath();\n            ctx.moveTo(0, this.r);\n            ctx.lineTo(-this.r, 0);\n            ctx.lineTo(0, -this.r);\n            ctx.lineTo(this.r, 0);\n            ctx.closePath();\n            ctx.fill();\n        } else if (this.type === 'fast') {\n            ctx.beginPath();\n            ctx.moveTo(0, this.r);\n            ctx.lineTo(-this.r * 0.75, -this.r);\n            ctx.lineTo(this.r * 0.75, -this.r);\n            ctx.closePath();\n            ctx.fill();\n        } else {\n            ctx.beginPath();\n            ctx.arc(0, 0, this.r, 0, Math.PI * 2);\n            ctx.fill();\n        }\n\n        ctx.shadowBlur = 0;\n\n        // Odoln\u00ed nep\u0159\u00e1tel\u00e9 uk\u00e1\u017eou zb\u00fdvaj\u00edc\u00ed \u017eivot, jakmile schytaj\u00ed prvn\u00ed r\u00e1nu\n        if (this.hp < this.maxHp && (this.type === 'tank' || this.type === 'destroyer')) {\n            const w = this.r * 1.7;\n            ctx.fillStyle = 'rgba(0,0,0,0.55)';\n            ctx.fillRect(-w / 2, -this.r - 9, w, 4);\n            ctx.fillStyle = '#ffdd33';\n            ctx.fillRect(-w / 2, -this.r - 9, w * Math.max(0, this.hp / this.maxHp), 4);\n        }\n\n        ctx.restore();\n    }\n}\n//======================================================================\n//  BOSSOV\u00c9\n//======================================================================\n//  Ka\u017ed\u00fd boss je stavov\u00fd automat: p\u0159esun -> n\u00e1dech -> \u00fatok -> oddech.\n//  N\u00e1dech je v\u017edy vid\u011bt dop\u0159edu, tak\u017ee z\u00e1sah je chyba hr\u00e1\u010de, ne n\u00e1hoda.\n//  F\u00e1ze se m\u011bn\u00ed podle zb\u00fdvaj\u00edc\u00edho \u017eivota a m\u011bn\u00ed tempo i skladbu \u00fatok\u016f.\n\nconst BOSS_TYPES = [\n    {\n        name: 'STR\u00c1\u017dCE',\n        color: '#ff3355',\n        attacks: ['burst', 'fan'],\n        rage: 'radial',\n        hpMul: 1.0,\n        desc: 'Dr\u017e\u00ed linii a st\u0159\u00edl\u00ed m\u00ed\u0159en\u00e9 salvy.'\n    },\n    {\n        name: '\u00daLOVEC',\n        color: '#ff9500',\n        attacks: ['minions', 'fan', 'burst'],\n        rage: 'rain',\n        hpMul: 1.05,\n        desc: 'Pos\u00edl\u00e1 do boje rychl\u00edky.'\n    },\n    {\n        name: 'TRH\u00c1\u010c',\n        color: '#ff0055',\n        attacks: ['charge', 'burst', 'fan'],\n        rage: 'charge',\n        hpMul: 1.05,\n        desc: 'Nal\u00e9t\u00e1v\u00e1 p\u0159\u00edmo na lo\u010f.'\n    },\n    {\n        name: 'V\u00cdR',\n        color: '#aa55ff',\n        attacks: ['spiral', 'radial', 'burst'],\n        rage: 'spiral',\n        hpMul: 1.1,\n        desc: 'Rozs\u00e9v\u00e1 st\u0159ely do spir\u00e1ly.'\n    },\n    {\n        name: 'PRIZMA',\n        color: '#00ddff',\n        attacks: ['beam', 'fan', 'burst'],\n        rage: 'beam',\n        hpMul: 1.1,\n        desc: 'Vypaluje sloup energie.'\n    },\n    {\n        name: 'ARCHONT',\n        color: '#ff00cc',\n        attacks: ['radial', 'charge', 'beam', 'spiral', 'minions'],\n        rage: 'radial',\n        hpMul: 1.15,\n        desc: 'Um\u00ed v\u0161echno a nic neodpou\u0161t\u00ed.'\n    },\n    {\n        name: 'BA\u0160TA',\n        color: '#ffaa00',\n        attacks: ['radial', 'pulse', 'burst'],\n        rage: 'pulse',\n        hpMul: 1.2,\n        desc: 'Byteln\u00e1 pevnost, co vys\u00edl\u00e1 tlakov\u00e9 vlny.'\n    },\n    {\n        name: 'NEMESIS',\n        color: '#ff003c',\n        attacks: ['burst', 'fan', 'radial', 'spiral', 'charge', 'beam', 'minions', 'pulse'],\n        rage: 'pulse',\n        hpMul: 1.35,\n        desc: 'Posledn\u00ed zkou\u0161ka - zvl\u00e1d\u00e1 v\u0161e.'\n    }\n];\n\nclass Boss {\n    constructor(game, level, hardMul) {\n        const def = BOSS_TYPES[Math.min(level - 1, BOSS_TYPES.length - 1)];\n\n        this.game = game;\n        this.type = 'boss';\n        this.level = level;\n        this.def = def;\n        this.name = def.name;\n        this.color = def.color;\n\n        this.r = 44;\n        this.maxHp = Math.round((35 + level * 58 + level * level * 9) * def.hpMul * hardMul);\n        this.hp = this.maxHp;\n\n        this.x = game.width / 2;\n        this.y = -90;\n        this.tx = this.x;\n        this.ty = 132;\n\n        this.scoreVal = 120 * level;\n        this.coinAmt = 240 + level * 120;\n\n        this.hitFlash = 0;\n        this.phase = 1;\n        this.t = 0;\n        this.spin = 0;\n        this.dead = false;\n\n        this.state = 'ENTRY';\n        this.stateT = 0;\n        this.attack = null;\n        this.attackT = 0;\n        this.attackStep = 0;\n        this.shotTimer = 0;\n        this.lastAttack = null;\n        this.aim = { x: 0, y: 0 };\n\n        Sounds.bossSpawn();\n    }\n\n    get hpPct() { return U.clamp(this.hp / this.maxHp, 0, 1); }\n    get indestructible() { return false; }\n\n    // Vy\u0161\u0161\u00ed f\u00e1ze a vy\u0161\u0161\u00ed level zrychluj\u00ed cel\u00fd cyklus\n    get tempo() { return 1 / (1 + (this.phase - 1) * 0.22 + Math.min(this.level, 10) * 0.035); }\n\n    setState(s, time) {\n        this.state = s;\n        this.stateT = time || 0;\n    }\n\n    //---------------------------------------------------------------- f\u00e1ze\n\n    checkPhase(game) {\n        const want = this.hpPct <= 0.33 ? 3 : (this.hpPct <= 0.66 ? 2 : 1);\n        if (want <= this.phase) return;\n\n        this.phase = want;\n\n        game.shake = Math.max(game.shake, 16);\n        game.showEvent(this.phase === 3 ? 'ZU\u0158IVOST' : 'F\u00c1ZE ' + this.phase, this.color);\n        game.texts.push(new FloatingText(this.x, this.y - 60, 'F\u00c1ZE ' + this.phase, this.color, 18));\n        Sounds.phase();\n\n        for (let i = 0; i < 26; i++) {\n            game.particles.push(new Particle(this.x, this.y, this.color, U.rand(3, 8), U.rand(2, 5), 0.03));\n        }\n\n        // Vstup do f\u00e1ze v\u017edy vykryje kruhov\u00e1 salva, aby zm\u011bna byla c\u00edtit\n        this.startAttack('radial');\n    }\n\n    //---------------------------------------------------------------- pohyb\n\n    pickPosition(game) {\n        const p = game.player;\n        const margin = this.r + 24;\n\n        // C\u00edl se posouv\u00e1 k hr\u00e1\u010di, ale nikdy p\u0159esn\u011b na n\u011bj - hr\u00e1\u010d m\u00e1 v\u017edy \u00fanikovou stranu\n        const wanted = U.lerp(this.x, p.x, 0.45) + U.rand(-90, 90);\n\n        this.tx = U.clamp(wanted, margin, game.width - margin);\n        this.ty = U.rand(100, 100 + 50 + this.phase * 22);\n    }\n\n    moveToTarget(dt, game, rate) {\n        const f = dt / 16;\n        const k = Math.min(1, (rate || 0.055) * f);\n\n        this.x = U.lerp(this.x, this.tx, k);\n        this.y = U.lerp(this.y, this.ty, k);\n        this.x = U.clamp(this.x, this.r, game.width - this.r);\n    }\n\n    update(dt, game) {\n        this.t += dt;\n        if (this.hitFlash > 0) this.hitFlash -= dt;\n\n        this.checkPhase(game);\n        this.stateT -= dt;\n\n        switch (this.state) {\n            case 'ENTRY':\n                this.y += 3.2 * (dt / 16);\n                this.x = U.lerp(this.x, game.width / 2, 0.06);\n                if (this.y >= 132) {\n                    this.y = 132;\n                    this.pickPosition(game);\n                    this.setState('MOVE', 900 * this.tempo);\n                }\n                break;\n\n            case 'MOVE':\n                this.moveToTarget(dt, game, 0.05 + this.phase * 0.012);\n                this.y += Math.sin(this.t * 0.003) * 0.4 * (dt / 16);\n\n                if (this.stateT <= 0) {\n                    this.chooseAttack(game);\n                }\n                break;\n\n            case 'TELEGRAPH':\n                // N\u00e1dech: boss couvne a rozsv\u00edt\u00ed se, hr\u00e1\u010d m\u00e1 \u010das se p\u0159esunout\n                this.y = U.lerp(this.y, this.ty - 14, 0.08 * (dt / 16));\n                if (this.stateT <= 0) this.beginAttack(game);\n                break;\n\n            case 'ATTACK':\n                this.runAttack(dt, game);\n                break;\n\n            case 'RECOVER':\n                this.moveToTarget(dt, game, 0.03);\n                if (this.stateT <= 0) {\n                    this.pickPosition(game);\n                    this.setState('MOVE', U.rand(650, 1000) * this.tempo);\n                }\n                break;\n        }\n    }\n\n    //---------------------------------------------------------------- volba \u00fatoku\n\n    chooseAttack(game) {\n        let pool = this.def.attacks.slice();\n\n        if (this.phase >= 3 && this.def.rage) pool.push(this.def.rage, this.def.rage);\n        if (pool.length > 1 && this.lastAttack) {\n            const filtered = pool.filter(a => a !== this.lastAttack);\n            if (filtered.length) pool = filtered;\n        }\n\n        this.startAttack(U.pick(pool));\n    }\n\n    startAttack(name) {\n        this.attack = name;\n        this.lastAttack = name;\n        this.attackT = 0;\n        this.attackStep = 0;\n        this.shotTimer = 0;\n\n        const telegraph = Math.max(220, (name === 'charge' || name === 'beam' || name === 'pulse' ? 600 : 440) * this.tempo);\n        this.setState('TELEGRAPH', telegraph);\n        Sounds.telegraph();\n    }\n\n    beginAttack(game) {\n        this.aim = { x: game.player.x, y: game.player.y };\n        this.setState('ATTACK', 0);\n        this.attackT = 0;\n\n        if (this.attack === 'beam') {\n            const sweep = this.phase >= 2 ? U.rand(-1.5, 1.5) * this.phase : 0;\n            game.beams.push(new Beam(this, 22 + this.phase * 5, 620, 700 + this.phase * 120, sweep));\n            Sounds.beam();\n        }\n\n        if (this.attack === 'minions') {\n            const n = 2 + this.phase;\n            for (let i = 0; i < n; i++) {\n                const e = new Enemy(this.x + U.rand(-60, 60), this.y + 20, 'fast', game.diffMult);\n                e.vx = U.rand(-1.4, 1.4);\n                game.enemies.push(e);\n                game.particles.push(new Particle(e.x, e.y, this.color, 3, 3, 0.05));\n            }\n        }\n\n        if (this.attack === 'pulse') {\n            const rings = this.phase >= 3 ? 3 : (this.phase === 2 ? 2 : 1);\n            for (let i = 0; i < rings; i++) {\n                game.shockwaves.push(new Shockwave(this.x, this.y, this.color, i * 260));\n            }\n            Sounds.beam();\n        }\n    }\n\n    endAttack() {\n        this.attack = null;\n        this.setState('RECOVER', U.rand(420, 760) * this.tempo);\n    }\n\n    //---------------------------------------------------------------- \u00fatoky\n\n    fire(game, angle, speed, dmg, r) {\n        game.bullets.push(new Bullet(\n            this.x + Math.cos(angle) * (this.r * 0.6),\n            this.y + Math.sin(angle) * (this.r * 0.6),\n            Math.cos(angle) * speed,\n            Math.sin(angle) * speed,\n            dmg === undefined ? 9 : dmg,\n            this.color,\n            true,\n            r || 6\n        ));\n    }\n\n    angleToPlayer(game) {\n        return Math.atan2(game.player.y - this.y, game.player.x - this.x);\n    }\n\n    runAttack(dt, game) {\n        this.attackT += dt;\n        this.shotTimer -= dt;\n\n        switch (this.attack) {\n\n            // M\u00ed\u0159en\u00e9 salvy: nejjednodu\u0161\u0161\u00ed \u00fatok, u\u010d\u00ed hr\u00e1\u010de uh\u00fdbat do strany\n            case 'burst': {\n                const shots = 2 + this.phase;\n                if (this.shotTimer <= 0) {\n                    this.shotTimer = 200 * this.tempo;\n                    const a = this.angleToPlayer(game);\n                    this.fire(game, a, 6.2, 9);\n                    Sounds.enemyShoot();\n                    this.attackStep++;\n                }\n                if (this.attackStep >= shots) this.endAttack();\n                break;\n            }\n\n            // V\u011bj\u00ed\u0159: nut\u00ed hr\u00e1\u010de vybrat si mezeru d\u0159\u00edv, ne\u017e dolet\u00ed\n            case 'fan': {\n                if (this.attackStep === 0) {\n                    const n = 4 + this.phase * 2;\n                    const base = this.angleToPlayer(game);\n                    const spread = 0.62 + this.phase * 0.12;\n\n                    for (let i = 0; i < n; i++) {\n                        const a = base - spread / 2 + (spread / (n - 1)) * i;\n                        this.fire(game, a, 5.4, 9);\n                    }\n\n                    Sounds.enemyShoot();\n                    this.attackStep = 1;\n                }\n                if (this.attackT > 420) this.endAttack();\n                break;\n            }\n\n            // Kruh: prostor se uzav\u00edr\u00e1 ze v\u0161ech stran, \u0159e\u0161\u00ed se pozic\u00ed p\u0159edem\n            case 'radial': {\n                const waves = Math.min(3, this.phase);\n                if (this.shotTimer <= 0) {\n                    this.shotTimer = 360 * this.tempo;\n                    const n = 9 + this.phase * 3;\n                    const off = this.attackStep * (Math.PI / n);\n\n                    for (let i = 0; i < n; i++) {\n                        this.fire(game, off + (Math.PI * 2 / n) * i, 4.4, 9);\n                    }\n\n                    Sounds.enemyShoot();\n                    this.attackStep++;\n                }\n                if (this.attackStep >= waves) this.endAttack();\n                break;\n            }\n\n            // Spir\u00e1la: souvisl\u00fd proud, hr\u00e1\u010d mus\u00ed krou\u017eit\n            case 'spiral': {\n                if (this.shotTimer <= 0) {\n                    this.shotTimer = 86;\n                    this.spin += 0.38;\n                    const arms = this.phase >= 3 ? 3 : 2;\n\n                    for (let i = 0; i < arms; i++) {\n                        this.fire(game, this.spin + (Math.PI * 2 / arms) * i, 4.3, 8, 5);\n                    }\n\n                    this.attackStep++;\n                    if (this.attackStep % 6 === 0) Sounds.enemyShoot();\n                }\n                if (this.attackT > 1200 + this.phase * 250) this.endAttack();\n                break;\n            }\n\n            // D\u00e9\u0161\u0165: pokr\u00fdv\u00e1 celou \u0161\u00ed\u0159ku, bezpe\u010dno je jen v pohybu\n            case 'rain': {\n                if (this.shotTimer <= 0) {\n                    this.shotTimer = 135;\n                    game.bullets.push(new Bullet(U.rand(15, game.width - 15), -10, 0, 4.4 + this.phase * 0.4, 8, this.color, true, 6));\n                    this.attackStep++;\n                }\n                if (this.attackT > 1600) this.endAttack();\n                break;\n            }\n\n            // N\u00e1let: fyzick\u00fd \u00fatok, trest\u00e1 st\u00e1n\u00ed na m\u00edst\u011b\n            case 'charge': {\n                const f = dt / 16;\n\n                if (this.attackStep === 0) {\n                    this.y = U.lerp(this.y, 90, 0.1 * f);\n                    if (this.attackT > 320) {\n                        this.aim = { x: game.player.x, y: game.player.y };\n                        this.attackStep = 1;\n                        this.attackT = 0;\n                    }\n                } else if (this.attackStep === 1) {\n                    const a = Math.atan2(this.aim.y - this.y, this.aim.x - this.x);\n                    const sp = 11 + this.phase * 1.6;\n\n                    this.x += Math.cos(a) * sp * f;\n                    this.y += Math.sin(a) * sp * f;\n\n                    game.particles.push(new Particle(this.x, this.y, this.color, U.rand(1, 3), U.rand(2, 4), 0.05));\n\n                    if (U.dist(this.x, this.y, this.aim.x, this.aim.y) < 30 || this.attackT > 900 || this.y > game.height - 60) {\n                        this.attackStep = 2;\n                        this.attackT = 0;\n                        this.pickPosition(game);\n                        this.ty = U.rand(100, 150);\n                        game.shake = Math.max(game.shake, 8);\n                    }\n                } else {\n                    this.moveToTarget(dt, game, 0.05);\n                    if (this.attackT > 620) this.endAttack();\n                }\n\n                this.x = U.clamp(this.x, this.r, game.width - this.r);\n                this.y = U.clamp(this.y, this.r, game.height - this.r);\n                break;\n            }\n\n            case 'minions':\n                if (this.attackT > 600) this.endAttack();\n                break;\n\n            case 'beam': {\n                this.x = U.lerp(this.x, this.tx, 0.02 * (dt / 16));\n                if (this.attackT > 1500 + this.phase * 120) this.endAttack();\n                break;\n            }\n\n            // Tlakov\u00e1 vlna: n\u00e1dech po\u0161le rozp\u00ednaj\u00edc\u00ed se kruhy, boss mezit\u00edm jen \u010dek\u00e1\n            case 'pulse': {\n                const rings = this.phase >= 3 ? 3 : (this.phase === 2 ? 2 : 1);\n                if (this.attackT > 500 + rings * 300) this.endAttack();\n                break;\n            }\n\n            default:\n                this.endAttack();\n        }\n    }\n\n    //---------------------------------------------------------------- kresba\n\n    draw(ctx) {\n        const telegraphing = this.state === 'TELEGRAPH';\n        const charging = this.attack === 'charge' && this.attackStep === 1;\n\n        ctx.save();\n        ctx.translate(this.x, this.y);\n\n        // Aura s\u00edl\u00ed s f\u00e1z\u00ed, tak\u017ee je stav bosse \u010diteln\u00fd i perifern\u011b\n        const auraR = this.r + 16 + Math.sin(this.t * 0.004) * 4;\n        const aura = ctx.createRadialGradient(0, 0, this.r * 0.5, 0, 0, auraR);\n        aura.addColorStop(0, 'rgba(0,0,0,0)');\n        aura.addColorStop(1, this.phase >= 3 ? 'rgba(255,40,40,0.28)' : 'rgba(255,255,255,0.09)');\n        ctx.fillStyle = aura;\n        ctx.beginPath();\n        ctx.arc(0, 0, auraR, 0, Math.PI * 2);\n        ctx.fill();\n\n        let body = this.color;\n        if (this.hitFlash > 0) body = '#ffffff';\n        else if (telegraphing && Math.floor(this.t / 90) % 2) body = '#ffffff';\n        else if (charging) body = '#ffdddd';\n\n        ctx.fillStyle = body;\n        ctx.shadowColor = this.color;\n        ctx.shadowBlur = telegraphing ? 30 : 16;\n\n        // Trup\n        ctx.beginPath();\n        ctx.moveTo(0, this.r);\n        ctx.lineTo(-this.r * 0.55, this.r * 0.4);\n        ctx.lineTo(-this.r, -this.r * 0.45);\n        ctx.lineTo(-this.r * 0.4, -this.r);\n        ctx.lineTo(this.r * 0.4, -this.r);\n        ctx.lineTo(this.r, -this.r * 0.45);\n        ctx.lineTo(this.r * 0.55, this.r * 0.4);\n        ctx.closePath();\n        ctx.fill();\n\n        // K\u0159\u00eddla\n        ctx.shadowBlur = 0;\n        ctx.fillStyle = 'rgba(0,0,0,0.35)';\n        ctx.beginPath();\n        ctx.moveTo(-this.r, -this.r * 0.45);\n        ctx.lineTo(-this.r * 1.5, this.r * 0.15);\n        ctx.lineTo(-this.r * 0.6, this.r * 0.25);\n        ctx.closePath();\n        ctx.fill();\n\n        ctx.beginPath();\n        ctx.moveTo(this.r, -this.r * 0.45);\n        ctx.lineTo(this.r * 1.5, this.r * 0.15);\n        ctx.lineTo(this.r * 0.6, this.r * 0.25);\n        ctx.closePath();\n        ctx.fill();\n\n        // J\u00e1dro\n        const core = telegraphing ? 1 : 0.55 + Math.sin(this.t * 0.006) * 0.2;\n        ctx.globalAlpha = core;\n        ctx.fillStyle = '#fff';\n        ctx.beginPath();\n        ctx.arc(0, -this.r * 0.15, this.r * 0.28, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.globalAlpha = 1;\n\n        // O\u010di podle f\u00e1ze\n        ctx.fillStyle = this.phase >= 3 ? '#ff2200' : '#ffffff';\n        for (let i = 0; i < this.phase; i++) {\n            ctx.fillRect(-10 + i * 10 - (this.phase - 1) * 5 + 5 - 5, -this.r * 0.55, 4, 4);\n        }\n\n        ctx.restore();\n    }\n}\n\n//======================================================================\n//  RE\u017dIS\u00c9R VLN\n//======================================================================\n//  M\u00edsto n\u00e1hodn\u00e9ho kap\u00e1n\u00ed pos\u00edl\u00e1 hra \u010diteln\u00e9 \u00fatvary s pauzami mezi nimi.\n//  Pauza je prostor na sebr\u00e1n\u00ed power-upu a n\u00e1dech - bez n\u00ed je hra jen \u0161um.\n\nconst FORMATIONS = [\n    {\n        name: 'proud',\n        minPhase: 1,\n        build(g, phase) {\n            const x = U.rand(50, g.width - 50);\n            const n = 4 + Math.min(3, phase);\n            const out = [];\n            for (let i = 0; i < n; i++) out.push({ delay: i * 250, x, y: -30, type: 'basic' });\n            return out;\n        }\n    },\n    {\n        name: 'kl\u00edn',\n        minPhase: 1,\n        build(g) {\n            const cx = U.rand(g.width * 0.32, g.width * 0.68);\n            const out = [{ delay: 0, x: cx, y: -30, type: 'basic' }];\n            for (let i = 1; i <= 2; i++) {\n                out.push({ delay: i * 70, x: cx - i * 44, y: -30 - i * 26, type: 'basic' });\n                out.push({ delay: i * 70, x: cx + i * 44, y: -30 - i * 26, type: 'basic' });\n            }\n            return out;\n        }\n    },\n    {\n        name: 'k\u0159\u00eddla',\n        minPhase: 2,\n        build(g) {\n            const out = [];\n            for (let i = 0; i < 3; i++) {\n                out.push({ delay: i * 180, x: -20, y: 40 + i * 30, type: 'fast', vx: 2.4 });\n                out.push({ delay: i * 180 + 90, x: g.width + 20, y: 40 + i * 30, type: 'fast', vx: -2.4 });\n            }\n            return out;\n        }\n    },\n    {\n        name: 'st\u011bna',\n        minPhase: 2,\n        build(g, phase) {\n            const n = 4 + Math.min(2, phase - 1);\n            const out = [];\n            for (let i = 0; i < n; i++) {\n                out.push({ delay: i * 60, x: (g.width / (n + 1)) * (i + 1), y: -30, type: i % 2 ? 'basic' : 'fast' });\n            }\n            return out;\n        }\n    },\n    {\n        name: 't\u011b\u017ek\u00e1',\n        minPhase: 3,\n        build(g) {\n            return [\n                { delay: 0, x: U.rand(70, g.width - 70), y: -40, type: 'destroyer' },\n                { delay: 500, x: U.rand(40, g.width - 40), y: -30, type: 'basic' },\n                { delay: 900, x: U.rand(40, g.width - 40), y: -30, type: 'basic' }\n            ];\n        }\n    },\n    {\n        name: 'obrn\u011bnci',\n        minPhase: 3,\n        build(g) {\n            return [\n                { delay: 0, x: g.width * 0.3, y: -40, type: 'tank' },\n                { delay: 350, x: g.width * 0.7, y: -40, type: 'tank' },\n                { delay: 800, x: g.width * 0.5, y: -30, type: 'fast' }\n            ];\n        }\n    },\n    {\n        name: 'roj',\n        minPhase: 4,\n        build(g) {\n            const out = [];\n            for (let i = 0; i < 7; i++) {\n                out.push({ delay: i * 130, x: U.rand(40, g.width - 40), y: -30, type: 'fast', vx: U.rand(-1.2, 1.2) });\n            }\n            return out;\n        }\n    },\n    {\n        name: 'n\u00e1val',\n        minPhase: 6,\n        build(g) {\n            const out = [];\n            for (let i = 0; i < 5; i++) {\n                const t = i % 3 === 0 ? 'tank' : (i % 3 === 1 ? 'fast' : 'basic');\n                out.push({ delay: i * 90, x: U.rand(30, g.width - 30), y: -30, type: t });\n            }\n            return out;\n        }\n    }\n];\n\nclass Director {\n    constructor(game) {\n        this.game = game;\n        this.reset();\n    }\n\n    reset() {\n        this.wave = 0;\n        this.queue = [];\n        this.gap = 900;\n        this.lastName = '';\n    }\n\n    update(dt) {\n        const g = this.game;\n        // Boss Rush je \u010dist\u011b souboj s bossy - b\u011b\u017en\u00e9 vlny sem nepat\u0159\u00ed\n        if (g.bossActive || g.tutActive || g.mode === 'rush') return;\n\n        for (let i = this.queue.length - 1; i >= 0; i--) {\n            const s = this.queue[i];\n            s.delay -= dt;\n            if (s.delay <= 0) {\n                this.spawn(s);\n                this.queue.splice(i, 1);\n            }\n        }\n\n        this.gap -= dt;\n\n        // Dal\u0161\u00ed vlna p\u0159ijde a\u017e se uvoln\u00ed m\u00edsto - obrazovka se nezanese\n        if (this.gap <= 0 && this.queue.length === 0 && g.enemies.length <= 2) {\n            this.nextWave();\n        }\n    }\n\n    nextWave() {\n        const g = this.game;\n        const phase = g.phase;\n\n        let pool = FORMATIONS.filter(f => f.minPhase <= phase);\n        if (pool.length > 1 && this.lastName) {\n            const filtered = pool.filter(f => f.name !== this.lastName);\n            if (filtered.length) pool = filtered;\n        }\n\n        const form = U.pick(pool);\n        this.lastName = form.name;\n        this.wave++;\n\n        this.queue = form.build(g, phase);\n\n        const rush = g.currentEvent === 'rush';\n        let gap = Math.max(450, 1700 - phase * 95) * (rush ? 0.42 : 1);\n        if (g.mode === 'blitz') gap *= 0.7;\n        if (g.daily) gap /= g.daily.spawnMult;\n        this.gap = gap;\n    }\n\n    spawn(s) {\n        const g = this.game;\n        const e = new Enemy(s.x, s.y, s.type, g.diffMult);\n        if (s.vx) e.vx = s.vx;\n        g.enemies.push(e);\n    }\n}\n//======================================================================\n//  HERN\u00cd MANA\u017dER\n//======================================================================\n\nconst BOSS_THRESHOLDS = [150, 650, 1400, 2400, 3600, 5000, 6600, 8400, 10400, 12600];\n\n//======================================================================\n//  DENN\u00cd V\u00ddZVA\n//======================================================================\n//  \u017d\u00e1dn\u00fd server, \u017e\u00e1dn\u00e9 prav\u00e9 sd\u00edlen\u00e9 sem\u00ednko - m\u00edsto toho si ka\u017ed\u00fd den\n//  podle data deterministicky vybere jeden z n\u011bkolika pevn\u00fdch modifik\u00e1tor\u016f.\n//  Stejn\u00fd den = stejn\u00e1 v\u00fdzva pro ka\u017ed\u00e9ho, z\u00edtra jin\u00e1.\n\nconst DAILY_MODIFIERS = [\n    { name: 'Zlat\u00e1 hore\u010dka', desc: 'Dvojn\u00e1sobn\u00e9 mince, jinak norm\u00e1ln\u00ed hra.',\n        coinMult: 2, enemyHpMult: 1, dmgTakenMult: 1, fireRateMult: 1, spawnMult: 1, hpMult: 1, bossHpMult: 1, bossRewardMult: 1, bombsAllowed: true, powerupsAllowed: true },\n    { name: 'K\u0159ehc\u00ed nep\u0159\u00e1tel\u00e9', desc: 'Nep\u0159\u00e1tel\u00e9 maj\u00ed polovi\u010dn\u00ed \u017eivot i polovi\u010dn\u00ed odm\u011bnu.',\n        coinMult: 0.5, enemyHpMult: 0.5, dmgTakenMult: 1, fireRateMult: 1, spawnMult: 1, hpMult: 1, bossHpMult: 1, bossRewardMult: 1, bombsAllowed: true, powerupsAllowed: true },\n    { name: '\u017delezn\u00e1 v\u016fle', desc: '+50 % \u017eivot, ale nep\u0159\u00e1tel\u00e9 d\u00e1vaj\u00ed o polovinu v\u00edc po\u0161kozen\u00ed.',\n        coinMult: 1, enemyHpMult: 1, dmgTakenMult: 1.5, fireRateMult: 1, spawnMult: 1, hpMult: 1.5, bossHpMult: 1, bossRewardMult: 1, bombsAllowed: true, powerupsAllowed: true },\n    { name: 'Rychl\u00fd z\u00e1sah', desc: 'Polovi\u010dn\u00ed prodleva mezi v\u00fdst\u0159ely, ale bez bomb.',\n        coinMult: 1, enemyHpMult: 1, dmgTakenMult: 1, fireRateMult: 0.5, spawnMult: 1, hpMult: 1, bossHpMult: 1, bossRewardMult: 1, bombsAllowed: false, powerupsAllowed: true },\n    { name: 'Bou\u0159e', desc: 'Dvojn\u00e1sobn\u00e9 tempo vln, ale bez power-up\u016f.',\n        coinMult: 1, enemyHpMult: 1, dmgTakenMult: 1, fireRateMult: 1, spawnMult: 2, hpMult: 1, bossHpMult: 1, bossRewardMult: 1, bombsAllowed: true, powerupsAllowed: false },\n    { name: 'Vytrvalost', desc: 'Bossov\u00e9 maj\u00ed dvojn\u00e1sobn\u00fd \u017eivot, ale trojn\u00e1sobnou odm\u011bnu.',\n        coinMult: 1, enemyHpMult: 1, dmgTakenMult: 1, fireRateMult: 1, spawnMult: 1, hpMult: 1, bossHpMult: 2, bossRewardMult: 3, bombsAllowed: true, powerupsAllowed: true }\n];\n\nfunction todayKey() {\n    const d = new Date();\n    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');\n}\n\nfunction dailyModifierForToday() {\n    const key = todayKey();\n    let h = 0;\n    for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;\n    return DAILY_MODIFIERS[h % DAILY_MODIFIERS.length];\n}\n\nclass GameManager {\n    constructor() {\n        this.canvas = document.getElementById('gameCanvas');\n        this.ctx = this.canvas.getContext('2d', { alpha: false });\n\n        this.width = 0;\n        this.height = 0;\n        this.state = 'MENU';\n        this.isHardMode = false;\n        this.mode = 'normal';\n        this.daily = null;\n        this.lastTime = 0;\n        this.hudCache = {};\n\n        this.tutStep = 0;\n        this.tutActive = false;\n        this.holdFire = false;\n\n        this.director = new Director(this);\n        this.resetGameData();\n        this.initInput();\n        this.resize();\n\n        window.addEventListener('resize', () => this.resize());\n        window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 250));\n\n        document.addEventListener('visibilitychange', () => {\n            if (document.hidden && this.state === 'PLAY' && !this.tutActive) this.pause();\n        });\n\n        requestAnimationFrame(t => this.loop(t));\n    }\n\n    //---------------------------------------------------------------- stav\n\n    get phase() {\n        if (this.mode === 'blitz') {\n            // Bleskov\u00e1 vlna m\u011b\u0159\u00ed tempo \u010dasem do konce, ne sk\u00f3re - a\u0165 je tlak c\u00edtit od za\u010d\u00e1tku\n            return U.clamp(1 + Math.floor((180000 - this.modeTimeLeft) / 18000), 1, 10);\n        }\n        const byScore = 1 + Math.floor(this.score / 280);\n        const byTime = 1 + Math.floor(this.runTime / 65000);\n        return U.clamp(Math.max(byScore, Math.min(byTime, 6)), 1, 12);\n    }\n\n    get diffMult() {\n        let m = (this.isHardMode ? 1.5 : 1) * (1 + this.phase * 0.09);\n        if (this.daily) m *= this.daily.enemyHpMult;\n        return m;\n    }\n\n    get comboMult() {\n        return Math.min(8, 1 + Math.floor(this.combo / 4));\n    }\n\n    resetGameData() {\n        this.player = new Player(this.width || 400, this.height || 700);\n\n        this.bullets = [];\n        this.enemies = [];\n        this.particles = [];\n        this.powerups = [];\n        this.texts = [];\n        this.beams = [];\n        this.booms = [];\n\n        this.boss = null;\n        this.bossActive = false;\n        this.bossCount = 0;\n        this.bossNoHit = true;\n        this.shockwaves = [];\n\n        this.score = 0;\n        this.kills = 0;\n        this.coinsEarned = 0;\n        this.runTime = 0;\n\n        this.combo = 0;\n        this.comboTimer = 0;\n        this.bestCombo = 1;\n\n        this.shake = 0;\n        this.flash = 0;\n        this.whiteFlash = 0;\n\n        this.currentEvent = null;\n        this.eventDuration = 0;\n        this.eventCooldown = 12000;\n        this.asteroidTimer = 0;\n        this.lastPlayerHp = this.player.maxHp;\n\n        // Stav specifick\u00fd pro hern\u00ed re\u017eimy - mimo sv\u016fj re\u017eim jednodu\u0161e ne\u010dinn\u00fd\n        this.modeTimeLeft = 180000;\n        this.rushStreak = 0;\n        this.rushBreak = 0;\n        this.phoenixUsed = false;\n        this._lastStatSec = 0;\n\n        this.director.reset();\n        this.hudCache = {};\n    }\n\n    resize() {\n        const container = document.getElementById('game-container');\n        this.width = container.clientWidth;\n        this.height = container.clientHeight;\n\n        const dpr = Math.min(window.devicePixelRatio || 1, 2);\n        this.canvas.width = Math.round(this.width * dpr);\n        this.canvas.height = Math.round(this.height * dpr);\n        this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n\n        this.stars = Array.from({ length: 95 }, () => {\n            const layer = Math.floor(Math.random() * 3);\n            return {\n                x: Math.random() * this.width,\n                y: Math.random() * this.height,\n                s: 1 + layer * 0.8,\n                v: 0.35 + layer * 0.9,\n                a: 0.2 + layer * 0.3\n            };\n        });\n\n        if (this.player) {\n            this.player.gw = this.width;\n            this.player.gh = this.height;\n            this.player.x = Math.min(this.player.x, this.width - this.player.r);\n            this.player.y = Math.min(this.player.y, this.height - this.player.r);\n        }\n    }\n\n    //---------------------------------------------------------------- ovl\u00e1d\u00e1n\u00ed\n\n    initInput() {\n        this.input = { keys: {}, mode: 'keys', pointerActive: false, pointerTarget: { x: 0, y: 0 } };\n\n        const moveCodes = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'KeyA', 'KeyD', 'KeyW', 'KeyS'];\n\n        window.addEventListener('keydown', e => {\n            const focusTag = document.activeElement && document.activeElement.tagName;\n            if (focusTag === 'INPUT') return;\n\n            this.input.keys[e.code] = true;\n\n            if (moveCodes.includes(e.code)) {\n                e.preventDefault();\n                this.input.mode = 'keys';\n                if (this.tutStep === 3) this.advanceTutorialStep();\n            }\n\n            if (e.code === 'Escape' || e.code === 'KeyP') {\n                if (this.state === 'PLAY') this.pause();\n                else if (this.state === 'PAUSE') this.resume();\n            }\n\n            if (e.code === 'KeyM') UI.toggleSound();\n            if (e.code === 'KeyB') this.useBomb();\n\n            if (e.code === 'Enter' || e.code === 'Space') {\n                if (focusTag === 'BUTTON') return;\n                e.preventDefault();\n                if (this.state === 'MENU') this.start('normal');\n                else if (this.state === 'GAMEOVER') this.start(this.mode);\n                else if (this.state === 'PAUSE') this.resume();\n            }\n        });\n\n        window.addEventListener('keyup', e => { this.input.keys[e.code] = false; });\n\n        const setTarget = e => {\n            const rect = this.canvas.getBoundingClientRect();\n            const fingerOffset = e.pointerType === 'touch' ? 38 : 0;\n            this.input.pointerTarget = {\n                x: e.clientX - rect.left,\n                y: e.clientY - rect.top - fingerOffset\n            };\n        };\n\n        this.canvas.addEventListener('pointerdown', e => {\n            Sounds.init();\n            if (this.state !== 'PLAY') return;\n\n            if (this.canvas.setPointerCapture) {\n                try { this.canvas.setPointerCapture(e.pointerId); } catch (err) {}\n            }\n\n            this.input.mode = 'pointer';\n            this.input.pointerActive = true;\n            setTarget(e);\n            if (this.tutStep === 3) this.advanceTutorialStep();\n        });\n\n        this.canvas.addEventListener('pointermove', e => {\n            if (this.state !== 'PLAY') return;\n            if (e.pointerType === 'touch' && !this.input.pointerActive) return;\n\n            this.input.mode = 'pointer';\n            this.input.pointerActive = true;\n            setTarget(e);\n            if (this.tutStep === 3) this.advanceTutorialStep();\n        });\n\n        const endPointer = e => { if (e.pointerType === 'touch') this.input.pointerActive = false; };\n\n        this.canvas.addEventListener('pointerup', endPointer);\n        this.canvas.addEventListener('pointercancel', endPointer);\n        this.canvas.addEventListener('contextmenu', e => e.preventDefault());\n    }\n\n    //---------------------------------------------------------------- b\u011bh hry\n\n    start(mode) {\n        Storage.flush();\n        Sounds.init();\n        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();\n\n        this.mode = ['normal', 'hard', 'blitz', 'rush', 'zen', 'daily'].includes(mode) ? mode : 'normal';\n        this.isHardMode = (this.mode === 'hard');\n        this.daily = (this.mode === 'daily') ? dailyModifierForToday() : null;\n        this.tutActive = false;\n        this.holdFire = false;\n        this.tutStep = 0;\n        this.clearTutorialGlows();\n\n        document.getElementById('tut-layer').classList.add('hidden');\n        this.resetGameData();\n        this.state = 'PLAY';\n\n        // Denn\u00ed modifik\u00e1tor uprav\u00ed lod\u02c7 a\u017e po jej\u00edm vytvo\u0159en\u00ed - jednor\u00e1zov\u011b, ne jako trval\u00e1 vylep\u0161en\u00ed\n        if (this.daily) {\n            this.player.maxHp = Math.round(this.player.maxHp * this.daily.hpMult);\n            this.player.hp = this.player.maxHp;\n            this.player.baseFireRate = Math.max(40, Math.round(this.player.baseFireRate * this.daily.fireRateMult));\n            if (!this.daily.bombsAllowed) {\n                this.player.maxBombs = 0;\n                this.player.bombs = 0;\n            }\n        }\n\n        document.getElementById('menu-overlay').classList.add('hidden');\n        document.getElementById('gameover-overlay').classList.add('hidden');\n        document.getElementById('pause-overlay').classList.add('hidden');\n        document.getElementById('hud').classList.remove('hidden');\n        document.getElementById('btn-bomb').classList.toggle('hidden', !!this.daily && !this.daily.bombsAllowed);\n        document.getElementById('boss-bar').classList.add('hidden');\n        document.getElementById('game-container').classList.add('playing');\n\n        document.getElementById('hud-timer').classList.toggle('hidden', this.mode !== 'blitz');\n        document.getElementById('hud-streak').classList.toggle('hidden', this.mode !== 'rush');\n\n        this.lastTime = performance.now();\n\n        if (!Storage.data.tutorialDone) {\n            this.startTutorialDialog();\n        } else if (this.mode === 'rush') {\n            this.spawnRushBoss();\n        }\n    }\n\n    pause() {\n        if (this.state !== 'PLAY') return;\n        if (this.tutActive && this.tutStep !== 11) return;\n\n        this.state = 'PAUSE';\n        Storage.flush();\n        UI.refresh();\n        document.getElementById('pause-score').innerText = 'Sk\u00f3re ' + U.num(this.score);\n        document.getElementById('pause-overlay').classList.remove('hidden');\n    }\n\n    resume() {\n        if (this.state !== 'PAUSE') return;\n\n        this.state = 'PLAY';\n        this.player.applyStats();\n        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();\n        document.getElementById('pause-overlay').classList.add('hidden');\n        this.lastTime = performance.now();\n    }\n\n    quitToMenu() {\n        this.state = 'MENU';\n        Storage.flush();\n\n        this.tutActive = false;\n        this.holdFire = false;\n        this.clearTutorialGlows();\n\n        ['pause-overlay', 'gameover-overlay', 'hud', 'tut-layer', 'btn-bomb'].forEach(id => {\n            document.getElementById(id).classList.add('hidden');\n        });\n        document.getElementById('game-container').classList.remove('playing');\n\n        UI.refresh();\n        document.getElementById('menu-overlay').classList.remove('hidden');\n    }\n\n    gameOver(reason) {\n        this.state = 'GAMEOVER';\n\n        // Boss Rush m\u00e1 vlastn\u00ed jm\u00e9no pro smrt, i kdy\u017e mechanicky jde o stejnou ud\u00e1lost\n        const effectiveReason = (reason === 'death' && this.mode === 'rush') ? 'rush_death' : (reason || 'death');\n        if (effectiveReason !== 'timeup') Sounds.bigExplosion();\n\n        Storage.data.stats.runsPlayed = (Storage.data.stats.runsPlayed || 0) + 1;\n        Storage.data.stats.totalPlaytime = (Storage.data.stats.totalPlaytime || 0) + this.runTime;\n        Storage.data.stats.bestCombo = Math.max(Storage.data.stats.bestCombo || 0, this.bestCombo);\n        Storage.data.stats.longestRun = Math.max(Storage.data.stats.longestRun || 0, this.runTime);\n\n        if (this.mode === 'blitz' && effectiveReason === 'timeup') {\n            Storage.data.stats.blitzClears = (Storage.data.stats.blitzClears || 0) + 1;\n        }\n\n        const isRush = this.mode === 'rush';\n        const isDaily = this.mode === 'daily';\n        const primary = isRush ? this.rushStreak : this.score;\n\n        let prevBest, isRecord;\n        if (isDaily) {\n            // Denn\u00ed rekord plat\u00ed jen pro dne\u0161ek - jin\u00fd den, jin\u00e1 v\u00fdzva, jin\u00e1 nula\n            const today = todayKey();\n            prevBest = (Storage.data.daily.date === today) ? (Storage.data.daily.score || 0) : 0;\n            isRecord = primary > prevBest;\n            if (isRecord) Storage.data.daily = { date: today, score: primary };\n        } else {\n            prevBest = Storage.data.best[this.mode] || 0;\n            isRecord = primary > prevBest;\n            if (isRecord) Storage.data.best[this.mode] = primary;\n        }\n\n        Achv.check();\n        Storage.save();\n\n        const secs = Math.floor(this.runTime / 1000);\n        const time = Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0');\n\n        document.getElementById('hud').classList.add('hidden');\n        document.getElementById('btn-bomb').classList.add('hidden');\n        document.getElementById('game-container').classList.remove('playing');\n        document.getElementById('go-record').classList.toggle('hidden', !isRecord);\n\n        const headings = { death: 'LO\u010e ZNI\u010cENA', timeup: '\u010cAS VYPR\u0160EL', rush_death: 'S\u00c9RIE P\u0158ERU\u0160ENA' };\n        document.getElementById('go-heading').innerText = headings[effectiveReason] || headings.death;\n\n        document.getElementById('go-metric-label').innerText = isRush ? 'PORA\u017dEN\u00cd BOSSOV\u00c9 V \u0158AD\u011a' : 'SK\u00d3RE';\n        document.getElementById('go-score').innerText = U.num(primary);\n\n        const modeNames = { normal: 'Norm\u00e1ln\u00ed obt\u00ed\u017enost', hard: 'T\u011b\u017ek\u00e1 obt\u00ed\u017enost', blitz: 'Bleskov\u00e1 vlna', rush: 'Boss Rush', daily: 'Denn\u00ed v\u00fdzva' + (this.daily ? ' \u00b7 ' + this.daily.name : ''), zen: 'Zen' };\n        document.getElementById('go-sub').innerText =\n            (modeNames[this.mode] || modeNames.normal) + ' \u00b7 rekord ' + U.num(Math.max(prevBest, primary));\n\n        let gridHtml;\n        if (isRush) {\n            gridHtml = `\n                <div><b>${U.num(this.coinsEarned)}</b>minc\u00ed</div>\n                <div><b>${this.kills}</b>zni\u010deno</div>\n                <div><b>${U.num(this.score)}</b>sk\u00f3re</div>\n                <div><b>${time}</b>\u010das</div>`;\n        } else if (this.mode === 'blitz') {\n            gridHtml = `\n                <div><b>${U.num(this.coinsEarned)}</b>minc\u00ed</div>\n                <div><b>${this.kills}</b>zni\u010deno</div>\n                <div><b>\u00d7${this.bestCombo}</b>nejlep\u0161\u00ed kombo</div>\n                <div><b>${this.phase}</b>dosa\u017een\u00e1 f\u00e1ze</div>`;\n        } else {\n            gridHtml = `\n                <div><b>${U.num(this.coinsEarned)}</b>minc\u00ed</div>\n                <div><b>${this.kills}</b>zni\u010deno</div>\n                <div><b>\u00d7${this.bestCombo}</b>nejlep\u0161\u00ed kombo</div>\n                <div><b>${time}</b>\u010das</div>`;\n        }\n        document.getElementById('go-grid').innerHTML = gridHtml;\n\n        document.getElementById('gameover-overlay').classList.remove('hidden');\n    }\n\n    //---------------------------------------------------------------- efekty\n\n    showEvent(msg, color) {\n        const el = document.getElementById('event-text');\n        el.innerText = msg;\n        el.style.color = color || '#ff8800';\n        el.classList.add('show');\n\n        clearTimeout(this.eventTimer);\n        this.eventTimer = setTimeout(() => el.classList.remove('show'), 2200);\n    }\n\n    boom(x, y, color, amount, speed) {\n        for (let i = 0; i < amount; i++) {\n            this.particles.push(new Particle(x, y, color, U.rand(1.5, speed || 6), U.rand(2, 5), U.rand(0.02, 0.05)));\n        }\n    }\n\n    damagePlayer(amount, iframes) {\n        // Z\u00e1sah vykryt\u00fd \u0161t\u00edtem se st\u00e1le po\u010d\u00edt\u00e1 jako z\u00e1sah - achievement \"Bez \u0161kr\u00e1bnut\u00ed\"\n        // m\u00e1 znamenat skute\u010dn\u00e9 uh\u00fdb\u00e1n\u00ed, ne tankov\u00e1n\u00ed za \u0161t\u00edtem\n        if (this.boss) this.bossNoHit = false;\n\n        const realAmount = this.daily ? Math.round(amount * this.daily.dmgTakenMult) : amount;\n\n        const before = this.player.hp;\n        const wouldDie = this.player.takeDamage(realAmount, iframes);\n\n        if (this.player.hp < before) {\n            this.shake = Math.max(this.shake, 9);\n            this.flash = 400;\n            this.combo = 0;\n            this.comboTimer = 0;\n        }\n\n        if (!wouldDie) return false;\n\n        // Zen je klidn\u00fd nekone\u010dn\u00fd re\u017eim - smrt tu prost\u011b neexistuje\n        if (this.mode === 'zen') {\n            this.player.hp = 1;\n            this.player.invulnTimer = Math.max(this.player.invulnTimer, 900);\n            return false;\n        }\n\n        // F\u00e9nixovo j\u00e1dro: jednou za b\u011bh p\u0159e\u017eije\u0161 smrt\u00edc\u00ed z\u00e1sah s 1 HP\n        if (!this.tutActive && Achv.hasRelic('phoenix') && !this.phoenixUsed) {\n            this.phoenixUsed = true;\n            this.player.hp = 1;\n            this.player.invulnTimer = Math.max(this.player.invulnTimer, 2200);\n            this.shake = Math.max(this.shake, 20);\n            this.whiteFlash = 320;\n            Sounds.heal();\n            this.texts.push(new FloatingText(this.player.x, this.player.y - 30, 'F\u00c9NIX', '#ff8800', 20));\n            return false;\n        }\n\n        this.boom(this.player.x, this.player.y, '#00f0ff', 45, 9);\n        this.shake = 28;\n        this.gameOver('death');\n        return true;\n    }\n\n    addCombo() {\n        const before = this.comboMult;\n        this.combo++;\n        this.comboTimer = 2400;\n\n        const now = this.comboMult;\n        if (now > before) {\n            Sounds.combo(now);\n            this.bestCombo = Math.max(this.bestCombo, now);\n\n            if (now > (Storage.data.stats.bestCombo || 0)) {\n                Storage.data.stats.bestCombo = now;\n                Achv.check();\n            }\n        }\n    }\n\n    // Statistiky se b\u011bhem v\u00fdcviku v\u016fbec nezapisuj\u00ed, a\u0165 cvi\u010dn\u00e9 souboje nic neodemykaj\u00ed\n    trackStat(key, amount) {\n        if (this.tutActive) return;\n        Storage.data.stats[key] = (Storage.data.stats[key] || 0) + (amount === undefined ? 1 : amount);\n    }\n\n    coinMultiplier() {\n        // Vzestup u\u017e sem z\u00e1m\u011brn\u011b nevstupuje - jinak by hodn\u011b vzestoupen\u00fd hr\u00e1\u010d\n        // vyd\u011bl\u00e1val rychleji, a hra by se s ka\u017ed\u00fdm vzestupem d\u00e1l zrychlovala.\n        // Skute\u010dn\u00e1 odm\u011bna za vzestup jde do samostatn\u00e9 m\u011bny (Hv\u011bzdn\u00fd prach).\n        let m = (this.isHardMode ? 2 : 1) + Math.floor(this.phase / 3);\n        if (Achv.hasRelic('collector')) m *= 1.2;\n        if (this.daily) m *= this.daily.coinMult;\n        return m;\n    }\n\n    useBomb() {\n        if (this.state !== 'PLAY' || this.player.bombs <= 0) return;\n\n        this.player.bombs--;\n        this.player.invulnTimer = Math.max(this.player.invulnTimer, 1400);\n\n        this.whiteFlash = 420;\n        this.shake = 24;\n        Sounds.bomb();\n\n        // Nep\u0159\u00e1telsk\u00e9 st\u0159ely se rozpadnou na jiskry, a\u0165 je \u00faleva vid\u011bt\n        for (const b of this.bullets) {\n            if (b.isEnemy) this.particles.push(new Particle(b.x, b.y, b.color, U.rand(1, 3), 3, 0.05));\n        }\n        this.bullets = this.bullets.filter(b => !b.isEnemy);\n        this.beams.length = 0;\n        this.shockwaves.length = 0;\n\n        for (let i = this.enemies.length - 1; i >= 0; i--) {\n            const e = this.enemies[i];\n            if (e.indestructible) {\n                this.boom(e.x, e.y, '#888', 10);\n                this.enemies.splice(i, 1);\n                continue;\n            }\n            e.hitFlash = 120;\n            e.hp -= 50;\n            if (e.hp <= 0) this.killEnemy(i, true);\n        }\n\n        if (this.boss) {\n            this.boss.hitFlash = 140;\n            this.boss.hp -= 80;\n            this.boom(this.boss.x, this.boss.y, '#fff', 20);\n            if (this.boss.hp <= 0) this.killBoss();\n        }\n\n        this.trackStat('bombsUsed');\n        if (!this.tutActive) Achv.check();\n\n        this.updateHUD(true);\n    }\n\n    //---------------------------------------------------------------- smrt nep\u0159\u00e1tel\n\n    killEnemy(index, silent) {\n        const e = this.enemies[index];\n        if (!e) return;\n\n        if (!silent) Sounds.explosion();\n        this.boom(e.x, e.y, e.color, 16);\n\n        if (!this.tutActive) {\n            this.addCombo();\n\n            const gained = Math.round(e.scoreVal * this.comboMult);\n            this.score += gained;\n            this.kills++;\n            this.trackStat('totalKills');\n\n            if (this.comboMult > 1 && e.scoreVal > 0) {\n                this.texts.push(new FloatingText(e.x, e.y, '+' + gained, '#ffffff', 13));\n            }\n\n            const gain = Math.round((e.coinAmt || 0) * this.coinMultiplier());\n\n            if (gain) {\n                Storage.data.coins += gain;\n                Storage.data.cycleCoins = (Storage.data.cycleCoins || 0) + gain;\n                this.coinsEarned += gain;\n                this.trackStat('totalCoinsEarned', gain);\n                Storage.queueSave();\n            }\n\n            Achv.check();\n\n            // \u0160\u0165astn\u00e1 hv\u011bzda ze stromu Vzestupu zved\u00e1 \u0161anci na power-up, pom\u011br heal/buff z\u016fst\u00e1v\u00e1 stejn\u00fd\n            if (!this.daily || this.daily.powerupsAllowed) {\n                const dropChance = 0.11 + prestigeBonus('luck', 0.01);\n                const roll = Math.random();\n                if (roll < dropChance) {\n                    const types = roll < dropChance * 0.318 ? ['heal'] : ['triple', 'shield', 'rapid'];\n                    this.powerups.push(new Powerup(e.x, e.y, U.pick(types)));\n                }\n\n                // Vz\u00e1cn\u00fd bonusov\u00fd drop minc\u00ed - nez\u00e1visl\u00fd na power-upech v\u00fd\u0161, aby zab\u00edjen\u00ed\n                // d\u00e1valo i hmatateln\u00fd pocit odm\u011bny mimo jen pomalu tikaj\u00edc\u00ed HUD \u010d\u00edslo.\n                if (e.type !== 'asteroid' && Math.random() < 0.035) {\n                    this.powerups.push(new Powerup(e.x, e.y, 'coin'));\n                }\n            }\n        }\n\n        this.enemies.splice(index, 1);\n        this.checkTutorialClear();\n    }\n\n    killBoss() {\n        const b = this.boss;\n        if (!b) return;\n\n        Sounds.bigExplosion();\n        this.shake = 34;\n        this.whiteFlash = 200;\n        this.boom(b.x, b.y, b.color, 60, 10);\n        this.boom(b.x, b.y, '#ffffff', 25, 5);\n\n        // \u0158et\u011bz v\u00fdbuch\u016f d\u00e1 por\u00e1\u017ece v\u00e1hu, kterou jeden z\u00e1blesk nem\u00e1\n        for (let i = 0; i < 7; i++) {\n            this.booms.push({\n                t: 90 + i * 110,\n                x: b.x + U.rand(-b.r, b.r),\n                y: b.y + U.rand(-b.r, b.r),\n                color: i % 2 ? '#ffffff' : b.color\n            });\n        }\n\n        if (!this.tutActive) {\n            const gained = b.scoreVal;\n            this.score += gained;\n            this.kills++;\n            this.trackStat('totalBossKills');\n            if (this.bossNoHit) this.trackStat('noHitBosses');\n\n            this.texts.push(new FloatingText(b.x, b.y - 30, '+' + U.num(gained), b.color, 22));\n\n            const gain = Math.round(b.coinAmt * this.coinMultiplier() * (this.daily ? this.daily.bossRewardMult : 1));\n\n            Storage.data.coins += gain;\n            Storage.data.cycleCoins = (Storage.data.cycleCoins || 0) + gain;\n            this.coinsEarned += gain;\n            this.trackStat('totalCoinsEarned', gain);\n            Storage.save();\n\n            this.powerups.push(new Powerup(b.x - 26, b.y, 'heal'));\n            this.powerups.push(new Powerup(b.x + 26, b.y, 'triple'));\n            this.powerups.push(new Powerup(b.x, b.y + 26, 'shield'));\n\n            // Bomba za bosse je odm\u011bna, kter\u00e1 se hod\u00ed pr\u00e1v\u011b do dal\u0161\u00ed vlny\n            if (this.player.bombs < this.player.maxBombs) this.player.bombs++;\n            this.showEvent('BOSS ZNI\u010cEN', b.color);\n\n            Achv.check();\n        }\n\n        this.boss = null;\n        this.bossActive = false;\n        this.beams.length = 0;\n        this.shockwaves.length = 0;\n        document.getElementById('boss-bar').classList.add('hidden');\n\n        this.checkTutorialClear();\n\n        if (!this.tutActive && this.mode === 'rush') {\n            this.rushStreak++;\n            Storage.data.stats.bestRushStreak = Math.max(Storage.data.stats.bestRushStreak || 0, this.rushStreak);\n            Achv.check();\n\n            // Mal\u00e9 dopln\u011bn\u00ed sil mezi souboji, a\u0165 m\u00e1 s\u00e9rie \u0161anci pokra\u010dovat\n            this.player.hp = Math.min(this.player.maxHp, this.player.hp + this.player.maxHp * 0.12);\n            if (this.player.bombs < this.player.maxBombs) this.player.bombs++;\n\n            this.rushBreak = 2200;\n        }\n    }\n\n    nextBossScore() {\n        if (this.bossCount < BOSS_THRESHOLDS.length) return BOSS_THRESHOLDS[this.bossCount];\n        return BOSS_THRESHOLDS[BOSS_THRESHOLDS.length - 1] + (this.bossCount - BOSS_THRESHOLDS.length + 1) * 3400;\n    }\n\n    spawnBossInstance(level) {\n        let hardMul = this.isHardMode ? 1.45 : 1;\n        if (this.daily) hardMul *= this.daily.bossHpMult;\n\n        this.boss = new Boss(this, level, hardMul);\n        this.bossActive = true;\n        this.bossNoHit = true;\n\n        this.enemies.length = 0;\n        this.showEvent(this.boss.name, this.boss.color);\n\n        const bar = document.getElementById('boss-bar');\n        bar.classList.remove('hidden');\n        document.getElementById('boss-name').innerText = this.boss.name;\n        document.getElementById('boss-name').style.color = this.boss.color;\n        document.getElementById('boss-fill').style.background = this.boss.color;\n    }\n\n    spawnBoss() {\n        this.bossCount++;\n        this.spawnBossInstance(this.bossCount);\n    }\n\n    spawnRushBoss() {\n        this.spawnBossInstance(this.rushStreak + 1);\n    }\n\n    //---------------------------------------------------------------- hlavn\u00ed logika\n\n    updateLogic(dt) {\n        const f = dt / 16;\n        this.runTime += dt;\n\n        if (this.mode === 'blitz' && !this.tutActive) {\n            this.modeTimeLeft -= dt;\n            if (this.modeTimeLeft <= 0) {\n                this.modeTimeLeft = 0;\n                this.updateHUD(true);\n                this.gameOver('timeup');\n                return;\n            }\n        }\n\n        if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 0.05);\n        if (this.flash > 0) this.flash -= dt;\n        if (this.whiteFlash > 0) this.whiteFlash -= dt;\n\n        if (this.comboTimer > 0) {\n            this.comboTimer -= dt;\n            if (this.comboTimer <= 0) this.combo = 0;\n        }\n\n        // Dlouh\u00e9 p\u0159e\u017eit\u00ed se po\u010d\u00edt\u00e1 i za b\u011bhu, ne jen na konci, a\u0165 \u00fasp\u011bch nasko\u010d\u00ed hned\n        if (!this.tutActive) {\n            const sec = Math.floor(this.runTime / 1000);\n            if (sec !== this._lastStatSec) {\n                this._lastStatSec = sec;\n                if (sec > 0 && sec % 30 === 0) {\n                    Storage.data.stats.longestRun = Math.max(Storage.data.stats.longestRun || 0, this.runTime);\n                    Achv.check();\n                }\n            }\n        }\n\n        this.player.update(dt, this.input, this);\n\n        this.updateEvents(dt);\n        this.director.update(dt);\n\n        if (this.mode === 'rush' && !this.tutActive) {\n            if (!this.boss && !this.bossActive && this.rushBreak > 0) {\n                this.rushBreak -= dt;\n                if (this.rushBreak <= 0) {\n                    this.rushBreak = 0;\n                    this.spawnRushBoss();\n                }\n            }\n        } else if (!this.bossActive && !this.tutActive && this.score >= this.nextBossScore()) {\n            this.spawnBoss();\n        }\n\n        if (this.boss) {\n            this.boss.update(dt, this);\n            if (this.boss.hp <= 0) this.killBoss();\n        }\n\n        this.updateBeams(dt);\n        this.updateShockwaves(dt);\n        this.updateBullets(dt);\n        this.updatePowerups(dt);\n        this.updateEnemies(dt);\n\n        for (let i = this.booms.length - 1; i >= 0; i--) {\n            const b = this.booms[i];\n            b.t -= dt;\n            if (b.t <= 0) {\n                this.boom(b.x, b.y, b.color, 14, 7);\n                Sounds.explosion();\n                this.booms.splice(i, 1);\n            }\n        }\n\n        for (let i = this.particles.length - 1; i >= 0; i--) {\n            this.particles[i].update(dt);\n            if (this.particles[i].life <= 0) this.particles.splice(i, 1);\n        }\n\n        for (let i = this.texts.length - 1; i >= 0; i--) {\n            this.texts[i].update(dt);\n            if (this.texts[i].life <= 0) this.texts.splice(i, 1);\n        }\n\n        this.updateHUD();\n    }\n\n    updateEvents(dt) {\n        if (this.tutActive || this.mode === 'rush') return;\n\n        if (this.eventCooldown > 0) this.eventCooldown -= dt;\n\n        if (this.currentEvent) {\n            this.eventDuration -= dt;\n            if (this.eventDuration <= 0) {\n                this.currentEvent = null;\n                this.eventCooldown = 16000;\n            }\n        }\n\n        const canStart = !this.bossActive && !this.currentEvent && this.eventCooldown <= 0;\n\n        if (canStart && this.player.hp < this.lastPlayerHp && this.score > 350 && Math.random() < 0.4) {\n            this.currentEvent = 'rush';\n            this.eventDuration = 10000;\n            this.showEvent('N\u00c1LET', '#ff0055');\n        } else if (canStart && this.score > 500 && Math.random() < 0.0012) {\n            this.currentEvent = 'asteroids';\n            this.eventDuration = 12000;\n            this.asteroidTimer = 0;\n            this.showEvent('POLE ASTEROID\u016e', '#9aa1ad');\n        }\n\n        this.lastPlayerHp = this.player.hp;\n\n        if (this.currentEvent === 'asteroids') {\n            this.asteroidTimer -= dt;\n            if (this.asteroidTimer <= 0) {\n                this.asteroidTimer = U.rand(420, 780);\n                this.enemies.push(new Enemy(U.rand(30, this.width - 30), -50, 'asteroid', this.diffMult));\n            }\n        }\n    }\n\n    updateBeams(dt) {\n        for (let i = this.beams.length - 1; i >= 0; i--) {\n            const beam = this.beams[i];\n            beam.update(dt, this);\n\n            if (beam.firing && !this.tutActive) {\n                const reach = beam.w * 0.75 + this.player.hitR;\n                if (Math.abs(beam.x - this.player.x) < reach && this.player.y > (beam.boss ? beam.boss.y : 0)) {\n                    if (this.damagePlayer(14, 620)) return;\n                }\n            }\n\n            if (beam.dead) this.beams.splice(i, 1);\n        }\n    }\n\n    updateShockwaves(dt) {\n        for (let i = this.shockwaves.length - 1; i >= 0; i--) {\n            const sw = this.shockwaves[i];\n            if (!sw) break;\n            sw.update(dt);\n\n            if (sw.active && !sw.hit && !this.tutActive) {\n                const d = U.dist(sw.x, sw.y, this.player.x, this.player.y);\n                const pad = sw.band / 2 + this.player.hitR;\n                // Kontrolujeme prostor, kter\u00fd prstenec za tento sn\u00edmek skute\u010dn\u011b zametl,\n                // ne jen jeho okam\u017eit\u00fd polom\u011br - jinak by ho v\u00fdjime\u010dn\u011b dlouh\u00fd sn\u00edmek mohl p\u0159esko\u010dit\n                const lo = Math.min(sw.prevR, sw.r) - pad;\n                const hi = Math.max(sw.prevR, sw.r) + pad;\n                if (d >= lo && d <= hi) {\n                    sw.hit = true;\n                    if (this.damagePlayer(12, 500)) return;\n                }\n            }\n\n            if (sw.dead) this.shockwaves.splice(i, 1);\n        }\n    }\n\n    updateBullets(dt) {\n        for (let i = this.bullets.length - 1; i >= 0; i--) {\n            const b = this.bullets[i];\n            if (!b) break;\n            b.update(dt);\n\n            if (b.life <= 0 || b.y < -40 || b.y > this.height + 40 || b.x < -40 || b.x > this.width + 40) {\n                this.bullets.splice(i, 1);\n                continue;\n            }\n\n            if (!b.isEnemy) continue;\n\n            if (U.hit(b, this.player, b.r, this.player.hitR)) {\n                this.boom(b.x, b.y, b.color, 5, 3);\n                this.bullets.splice(i, 1);\n\n                // Ve v\u00fdcviku se neum\u00edr\u00e1, jen se u\u010d\u00ed uh\u00fdbat\n                if (this.tutActive) {\n                    Sounds.hit();\n                    continue;\n                }\n\n                if (this.damagePlayer(b.dmg, 400)) return;\n            }\n        }\n    }\n\n    updatePowerups(dt) {\n        for (let i = this.powerups.length - 1; i >= 0; i--) {\n            const p = this.powerups[i];\n            if (!p) break;\n            p.update(dt, this);\n\n            if (U.hit(p, this.player)) {\n                const pl = this.player;\n\n                if (p.type === 'triple') pl.tripleShotTimer = pl.tripleTime;\n                if (p.type === 'shield') pl.shieldTimer = pl.shieldTime;\n                if (p.type === 'rapid') pl.rapidTimer = pl.rapidTime;\n                if (p.type === 'heal') pl.heal(pl.healAmount);\n\n                if (p.type === 'coin') {\n                    // Vz\u00e1cn\u00fd bonusov\u00fd drop - v\u00fdrazn\u011b v\u00edc ne\u017e oby\u010dejn\u00fd zabit\u00fd nep\u0159\u00edtel,\n                    // a\u0165 to m\u00e1 hr\u00e1\u010d pro\u010d chytat a hra nep\u016fsob\u00ed bezcenn\u011b.\n                    const bonus = Math.round((60 + Math.random() * 90) * this.coinMultiplier());\n                    Storage.data.coins += bonus;\n                    Storage.data.cycleCoins = (Storage.data.cycleCoins || 0) + bonus;\n                    this.coinsEarned += bonus;\n                    this.trackStat('totalCoinsEarned', bonus);\n                    Storage.queueSave();\n                    this.texts.push(new FloatingText(p.x, p.y - 12, '+' + bonus + ' \ud83e\ude99', '#ffd700', 20));\n                } else {\n                    this.texts.push(new FloatingText(p.x, p.y - 12, POWERUP_STYLE[p.type].icon, p.color, 18));\n                }\n\n                if (p.type !== 'heal') Sounds.powerup();\n\n                this.powerups.splice(i, 1);\n\n                if (this.tutActive && (this.tutStep === 7 || this.tutStep === 8) && this.powerups.length === 0) {\n                    this.advanceTutorialStep();\n                }\n            } else if (p.y > this.height + 25) {\n                const missed = p.type;\n                this.powerups.splice(i, 1);\n\n                // Propadl\u00fd power-up by v\u00fdcvik nast\u00e1lo zasekl\n                if (this.tutActive && (this.tutStep === 7 || this.tutStep === 8)) {\n                    this.powerups.push(new Powerup(U.rand(this.width * 0.25, this.width * 0.75), -20, missed));\n                }\n            }\n        }\n    }\n\n    updateEnemies(dt) {\n        for (let i = this.enemies.length - 1; i >= 0; i--) {\n            const e = this.enemies[i];\n            if (!e) break;\n            e.update(dt, this);\n\n            if (e.y > this.height + e.r + 20) {\n                this.enemies.splice(i, 1);\n                this.checkTutorialClear();\n                continue;\n            }\n\n            if (U.hit(e, this.player, e.r * 0.82, this.player.r * 0.72)) {\n                const removable = !e.indestructible;\n\n                if (removable) {\n                    this.boom(e.x, e.y, e.color, 16);\n                    this.enemies.splice(i, 1);\n                }\n\n                const dmg = e.type === 'asteroid' ? 34 : (e.type === 'destroyer' ? 30 : Math.round(e.r * 0.9));\n\n                if (!this.tutActive) {\n                    if (this.damagePlayer(dmg, e.indestructible ? 900 : 400)) return;\n                } else {\n                    Sounds.hit();\n                }\n\n                this.checkTutorialClear();\n                if (removable) continue;\n            }\n        }\n\n        // Boss m\u00e1 vlastn\u00ed dotykov\u00fd z\u00e1sah, proto\u017ee z obrazovky nemiz\u00ed\n        if (this.boss && U.hit(this.boss, this.player, this.boss.r * 0.8, this.player.r * 0.72) && !this.tutActive) {\n            if (this.damagePlayer(26, 900)) return;\n        }\n\n        // Seznam c\u00edl\u016f sestavujeme a\u017e te\u010f, aby v n\u011bm nebyli mrtv\u00ed nep\u0159\u00e1tel\u00e9 z kroku v\u00fd\u0161e\n        const targets = this.boss ? this.enemies.concat([this.boss]) : this.enemies;\n\n        // Pole c\u00edl\u016f je momentka - pokud jedna st\u0159ela zabije nep\u0159\u00edtele, dal\u0161\u00ed st\u0159ela\n        // ve stejn\u00e9m sn\u00edmku by na jeho star\u00e9 sou\u0159adnice mohla m\u00ed\u0159it napr\u00e1zdno\n        const goneThisFrame = new Set();\n\n        for (let j = this.bullets.length - 1; j >= 0; j--) {\n            const b = this.bullets[j];\n            // Postup v\u00fdcviku vypr\u00e1zdn\u00ed pole uprost\u0159ed iterace, proto pojistka\n            if (!b) break;\n            if (b.isEnemy) continue;\n\n            for (let k = 0; k < targets.length; k++) {\n                const e = targets[k];\n                if (goneThisFrame.has(e)) continue;\n                if (!U.hit(b, e)) continue;\n\n                this.boom(b.x, b.y, '#ffffff', 3, 2.5);\n                this.bullets.splice(j, 1);\n\n                if (e.indestructible) break;\n\n                e.hp -= b.dmg;\n                e.hitFlash = 70;\n\n                if (e.hp <= 0) {\n                    goneThisFrame.add(e);\n                    if (e === this.boss) this.killBoss();\n                    else this.killEnemy(this.enemies.indexOf(e));\n                }\n                break;\n            }\n        }\n    }\n\n    //---------------------------------------------------------------- HUD\n\n    updateHUD(force) {\n        const c = this.hudCache;\n\n        if (force || c.score !== this.score) {\n            c.score = this.score;\n            document.getElementById('hud-score').innerText = U.num(this.score);\n        }\n\n        if (force || c.coins !== Storage.data.coins) {\n            c.coins = Storage.data.coins;\n            document.getElementById('hud-coins').innerText = U.num(Storage.data.coins);\n        }\n\n        const mult = this.comboMult;\n        if (force || c.mult !== mult) {\n            c.mult = mult;\n            const tag = document.getElementById('hud-combo');\n            tag.classList.toggle('hidden', mult < 2);\n            tag.innerText = '\u00d7' + mult;\n        }\n\n        if (this.mode === 'blitz') {\n            const secs = Math.max(0, Math.ceil(this.modeTimeLeft / 1000));\n            const label = Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0');\n            if (force || c.timer !== label) {\n                c.timer = label;\n                document.getElementById('hud-timer').innerText = label;\n            }\n        }\n\n        if (this.mode === 'rush') {\n            if (force || c.streak !== this.rushStreak) {\n                c.streak = this.rushStreak;\n                document.getElementById('hud-streak').innerText = 'S\u00e9rie ' + this.rushStreak;\n            }\n        }\n\n        const hp = Math.max(0, Math.ceil(this.player.hp));\n        if (force || c.hp !== hp || c.maxHp !== this.player.maxHp) {\n            c.hp = hp;\n            c.maxHp = this.player.maxHp;\n\n            const pct = U.clamp(hp / this.player.maxHp, 0, 1);\n            const fill = document.getElementById('hp-fill');\n\n            fill.style.width = (pct * 100) + '%';\n            fill.classList.toggle('mid', pct <= 0.55 && pct > 0.25);\n            fill.classList.toggle('low', pct <= 0.25);\n            document.getElementById('hp-num').innerText = hp + '/' + this.player.maxHp;\n        }\n\n        const bombs = this.player.bombs;\n        if (force || c.bombs !== bombs) {\n            c.bombs = bombs;\n            document.getElementById('bomb-count').innerText = bombs;\n            document.getElementById('btn-bomb').classList.toggle('empty', bombs <= 0);\n        }\n\n        if (this.boss) {\n            const pct = this.boss.hpPct;\n            if (force || c.bossHp !== pct) {\n                c.bossHp = pct;\n                document.getElementById('boss-fill').style.width = (pct * 100) + '%';\n            }\n            if (force || c.bossPhase !== this.boss.phase) {\n                c.bossPhase = this.boss.phase;\n                document.getElementById('boss-phase').innerText = 'f\u00e1ze ' + this.boss.phase + '/3';\n            }\n        }\n\n        const p = this.player;\n        const buffs = [\n            { id: 'shield', t: p.shieldTimer, max: p.shieldTime, color: '#00aaff', icon: '\ud83d\udee1\ufe0f' },\n            { id: 'triple', t: p.tripleShotTimer, max: p.tripleTime, color: '#ffcc00', icon: '\u26a1' },\n            { id: 'rapid', t: p.rapidTimer, max: p.rapidTime, color: '#ff4400', icon: '\ud83d\udd25' }\n        ].filter(b => b.t > 0);\n\n        const container = document.getElementById('powerup-timers');\n        const key = buffs.map(b => b.id).join(',');\n\n        // DOM se stav\u00ed jen p\u0159i zm\u011bn\u011b sady, jinak by se pop-in animace restartovala ka\u017ed\u00fd sn\u00edmek\n        if (key !== c.buffKey) {\n            c.buffKey = key;\n            container.innerHTML = buffs.map(b => `\n                <div class=\"buff-badge\" data-buff=\"${b.id}\">\n                    <svg viewBox=\"0 0 36 36\">\n                        <circle class=\"bg\" cx=\"18\" cy=\"18\" r=\"15.9155\" />\n                        <circle class=\"progress\" cx=\"18\" cy=\"18\" r=\"15.9155\" stroke=\"${b.color}\" />\n                    </svg>\n                    <span class=\"buff-icon\">${b.icon}</span>\n                </div>`).join('');\n        }\n\n        for (const b of buffs) {\n            const ring = container.querySelector(`[data-buff=\"${b.id}\"] .progress`);\n            if (ring) ring.style.strokeDashoffset = 100 - (b.t / b.max) * 100;\n        }\n    }\n\n    //---------------------------------------------------------------- kresba\n\n    draw() {\n        const ctx = this.ctx;\n\n        ctx.fillStyle = '#020617';\n        ctx.fillRect(0, 0, this.width, this.height);\n\n        ctx.save();\n        if (this.shake > 0) {\n            ctx.translate(U.rand(-this.shake, this.shake), U.rand(-this.shake, this.shake));\n        }\n\n        ctx.fillStyle = '#fff';\n        for (const s of this.stars) {\n            ctx.globalAlpha = s.a;\n            ctx.fillRect(s.x, s.y, s.s, s.s);\n        }\n        ctx.globalAlpha = 1;\n\n        if (this.state === 'PLAY' || this.state === 'PAUSE') {\n            for (const b of this.beams) b.draw(ctx, this);\n            for (const sw of this.shockwaves) sw.draw(ctx);\n            for (const p of this.powerups) p.draw(ctx);\n            for (const e of this.enemies) e.draw(ctx);\n            if (this.boss) this.boss.draw(ctx);\n            for (const b of this.bullets) b.draw(ctx);\n\n            this.player.draw(ctx);\n\n            for (const p of this.particles) p.draw(ctx);\n            for (const t of this.texts) t.draw(ctx);\n        }\n\n        ctx.restore();\n\n        this.drawOverlays(ctx);\n    }\n\n    drawOverlays(ctx) {\n        if (this.flash > 0) {\n            this.vignette(ctx, '255, 0, 60', Math.min(0.5, this.flash / 800));\n        }\n\n        // Trval\u00e9 varov\u00e1n\u00ed p\u0159i kritick\u00e9m \u017eivot\u011b\n        if (this.state === 'PLAY' && this.player.hp / this.player.maxHp < 0.25) {\n            const pulse = 0.14 + Math.abs(Math.sin(Date.now() / 340)) * 0.16;\n            this.vignette(ctx, '255, 0, 40', pulse);\n        }\n\n        if (this.whiteFlash > 0) {\n            ctx.fillStyle = `rgba(255,255,255,${Math.min(0.75, this.whiteFlash / 560)})`;\n            ctx.fillRect(0, 0, this.width, this.height);\n        }\n    }\n\n    vignette(ctx, rgb, alpha) {\n        const g = ctx.createRadialGradient(\n            this.width / 2, this.height / 2, Math.min(this.width, this.height) * 0.18,\n            this.width / 2, this.height / 2, Math.max(this.width, this.height) * 0.72\n        );\n\n        g.addColorStop(0, `rgba(${rgb}, 0)`);\n        g.addColorStop(1, `rgba(${rgb}, ${alpha})`);\n\n        ctx.fillStyle = g;\n        ctx.fillRect(0, 0, this.width, this.height);\n    }\n\n    updateStars(dt) {\n        const boost = this.state === 'PLAY' ? 1 + this.phase * 0.04 : 1;\n\n        for (const s of this.stars) {\n            s.y += s.v * boost * (dt / 16);\n            if (s.y > this.height) {\n                s.y = -2;\n                s.x = Math.random() * this.width;\n            }\n        }\n    }\n\n    loop(timestamp) {\n        let dt = timestamp - this.lastTime;\n        if (!Number.isFinite(dt) || dt < 0) dt = 16;\n        if (dt > 100) dt = 100;\n        this.lastTime = timestamp;\n\n        if (this.state === 'PLAY') this.updateLogic(dt);\n        if (this.state !== 'PAUSE') this.updateStars(dt);\n\n        this.draw();\n        requestAnimationFrame(t => this.loop(t));\n    }\n}\n//======================================================================\n//  V\u00ddCVIK\n//======================================================================\n//  Odd\u011blen\u00fd od hern\u00ed smy\u010dky, aby se logika hry nem\u00edchala s v\u00fdukou.\n\nconst TUT_LAST = 11;\nconst TUT_COMBAT_STEPS = [4, 5, 6, 9, 10];\n\nObject.assign(GameManager.prototype, {\n\n    startTutorialDialog() {\n        this.tutActive = true;\n        this.holdFire = true;\n        this.tutStep = 1;\n\n        document.getElementById('tut-layer').classList.remove('hidden');\n        this.setTutText('Ne\u017e vyraz\u00edte, m\u016f\u017eeme si proj\u00edt v\u00fdcvik. Trv\u00e1 asi minutu a nau\u010d\u00ed v\u00e1s v\u0161echno pot\u0159ebn\u00e9.');\n        this.setTutStepLabel();\n\n        document.getElementById('tut-buttons').innerHTML = `\n            <button class=\"btn btn-small\" id=\"btn-tut-yes\">Spustit v\u00fdcvik</button>\n            <button class=\"btn btn-small btn-danger\" id=\"btn-tut-no\">Rovnou hr\u00e1t</button>`;\n\n        document.getElementById('btn-tut-yes').onclick = () => this.advanceTutorialStep();\n        document.getElementById('btn-tut-no').onclick = () => this.endTutorial();\n        document.getElementById('btn-tut-skip').onclick = () => this.endTutorial();\n    },\n\n    setTutText(html) {\n        document.getElementById('tut-text').innerHTML = html;\n    },\n\n    setTutStepLabel() {\n        const el = document.getElementById('tut-step');\n        el.innerText = this.tutStep <= 1 ? 'V\u00ddCVIK' : 'KROK ' + (this.tutStep - 1) + ' Z ' + (TUT_LAST - 1);\n    },\n\n    clearTutorialGlows() {\n        ['hud-stats-group', 'btn-pause', 'btn-bomb'].forEach(id => {\n            const el = document.getElementById(id);\n            if (el) el.classList.remove('glow-highlight');\n        });\n\n        const circle = document.getElementById('tut-focus-circle');\n        if (circle) circle.classList.remove('show');\n    },\n\n    // Vol\u00e1 se po ka\u017ed\u00e9m \u00fabytku nep\u0159\u00e1tel; bez toho v\u00fdcvik uv\u00e1zne\n    checkTutorialClear() {\n        if (!this.tutActive) return;\n        if (!TUT_COMBAT_STEPS.includes(this.tutStep)) return;\n        if (this.enemies.length > 0 || this.boss) return;\n\n        this.advanceTutorialStep();\n    },\n\n    advanceTutorialStep() {\n        this.clearTutorialGlows();\n\n        this.enemies.length = 0;\n        this.bullets.length = 0;\n        this.powerups.length = 0;\n        this.beams.length = 0;\n        this.shockwaves.length = 0;\n\n        this.tutStep++;\n        this.setTutStepLabel();\n\n        const btns = document.getElementById('tut-buttons');\n        btns.innerHTML = '';\n        this.holdFire = true;\n\n        const next = label => {\n            btns.innerHTML = `<button class=\"btn btn-small\" id=\"btn-tut-next\">${label || 'Dal\u0161\u00ed'}</button>`;\n            document.getElementById('btn-tut-next').onclick = () => this.advanceTutorialStep();\n        };\n\n        switch (this.tutStep) {\n\n            case 2:\n                document.getElementById('hud-stats-group').classList.add('glow-highlight');\n                this.setTutText('Naho\u0159e m\u00e1te sk\u00f3re, mince a pruh \u017eivota. Rychle po sob\u011b zni\u010den\u00ed nep\u0159\u00e1tel\u00e9 zvednou n\u00e1sobi\u010d sk\u00f3re, kter\u00fd uvid\u00edte hned vedle minc\u00ed.');\n                next();\n                break;\n\n            case 3: {\n                const circle = document.getElementById('tut-focus-circle');\n                circle.style.left = (this.player.x - 32) + 'px';\n                circle.style.top = (this.player.y - 32) + 'px';\n                circle.style.width = '64px';\n                circle.style.height = '64px';\n                circle.classList.add('show');\n                this.setTutText('Tohle je va\u0161e lo\u010f. Zkuste s n\u00ed pohnout \u2014 t\u00e1hn\u011bte prstem, nebo pou\u017eijte \u0161ipky, WASD \u010di my\u0161.');\n                break;\n            }\n\n            case 4: {\n                this.holdFire = false;\n                const e = new Enemy(this.width / 2, 70, 'basic', 1);\n                e.speed = 0.45;\n                this.enemies.push(e);\n                this.setTutText('St\u0159\u00edl\u00edte automaticky, sta\u010d\u00ed m\u00ed\u0159it t\u011blem lodi. Zni\u010dte tohoto nep\u0159\u00edtele.');\n                break;\n            }\n\n            case 5: {\n                this.holdFire = false;\n                const fast = new Enemy(this.width * 0.3, 60, 'fast', 1);\n                const tank = new Enemy(this.width * 0.7, 60, 'tank', 1);\n                fast.speed = 0.8;\n                tank.speed = 0.35;\n                this.enemies.push(fast, tank);\n                this.setTutText('Fialov\u00fd rychl\u00edk se \u0159\u00edt\u00ed dol\u016f, ale sta\u010d\u00ed mu jedin\u00e1 r\u00e1na. Oran\u017eov\u00fd obrn\u011bnec je pomal\u00fd a vydr\u017e\u00ed n\u011bkolik z\u00e1sah\u016f.');\n                break;\n            }\n\n            case 6: {\n                this.holdFire = false;\n                const dest = new Enemy(this.width * 0.32, 60, 'destroyer', 1);\n                const ast = new Enemy(this.width * 0.72, 40, 'asteroid', 1);\n                dest.speed = 0.3;\n                dest.fireTimer = 900;\n                ast.speed = 0.6;\n                this.enemies.push(dest, ast);\n                this.setTutText('Rud\u00fd ni\u010ditel po v\u00e1s st\u0159\u00edl\u00ed a m\u00e1 hodn\u011b \u017eivota \u2014 uh\u00fdbejte do strany. \u0160ed\u00fd asteroid zni\u010dit nejde, ten se d\u00e1 jen obej\u00edt.');\n                break;\n            }\n\n            case 7:\n                this.powerups.push(new Powerup(this.width * 0.35, 120, 'triple'));\n                this.powerups.push(new Powerup(this.width * 0.65, 120, 'rapid'));\n                this.setTutText('\u00dato\u010dn\u00e9 power-upy: \u26a1 trojit\u00e1 st\u0159elba a \ud83d\udd25 rychlopalba. Seberte oba.');\n                break;\n\n            case 8:\n                this.powerups.push(new Powerup(this.width * 0.35, 120, 'shield'));\n                this.powerups.push(new Powerup(this.width * 0.65, 120, 'heal'));\n                this.setTutText('Obrann\u00e9 power-upy: \ud83d\udee1\ufe0f \u0161t\u00edt v\u00e1s na chv\u00edli ud\u011bl\u00e1 nezraniteln\u00fdmi, \u2764\ufe0f dopln\u00ed \u017eivot. Posledn\u00ed vte\u0159ina \u0161t\u00edtu blik\u00e1.');\n                break;\n\n            case 9: {\n                this.holdFire = false;\n\n                const boss = new Boss(this, 1, 1);\n                boss.maxHp = 45;\n                boss.hp = 45;\n                this.boss = boss;\n                this.bossActive = true;\n\n                const bar = document.getElementById('boss-bar');\n                bar.classList.remove('hidden');\n                document.getElementById('boss-name').innerText = boss.name;\n                document.getElementById('boss-name').style.color = boss.color;\n                document.getElementById('boss-fill').style.background = boss.color;\n\n                this.setTutText('Boss p\u0159ed ka\u017ed\u00fdm \u00fatokem zb\u011bl\u00e1 a nadechne se \u2014 to je va\u0161e chv\u00edle na \u00fahyb. Jak mu ub\u00fdv\u00e1 \u017eivot, p\u0159ep\u00edn\u00e1 do vy\u0161\u0161\u00edch f\u00e1z\u00ed a p\u0159itvrzuje.');\n                break;\n            }\n\n            case 10: {\n                this.player.bombs = 1;\n                document.getElementById('btn-bomb').classList.add('glow-highlight');\n\n                for (let i = 0; i < 5; i++) {\n                    const e = new Enemy((this.width / 6) * (i + 1), 90 + (i % 2) * 40, 'basic', 1);\n                    e.speed = 0;\n                    this.enemies.push(e);\n                }\n\n                this.setTutText('Bomba vy\u010dist\u00ed obrazovku od nep\u0159\u00e1tel i st\u0159el a na chv\u00edli v\u00e1s ochr\u00e1n\u00ed. M\u00e1te jednu \u2014 pou\u017eijte ji tla\u010d\u00edtkem vpravo dole (nebo kl\u00e1vesou B).');\n                break;\n            }\n\n            case 11:\n                document.getElementById('btn-pause').classList.add('glow-highlight');\n                this.setTutText('Tla\u010d\u00edtkem pauzy hru kdykoliv zastav\u00edte a za mince nakoup\u00edte trval\u00e1 vylep\u0161en\u00ed lodi. Plat\u00ed i do dal\u0161\u00edch her. V menu najde\u0161 i dal\u0161\u00ed hern\u00ed re\u017eimy, \u00fasp\u011bchy a vzestup pro pokro\u010dil\u00e9.');\n                btns.innerHTML = `<button class=\"btn btn-small\" id=\"btn-tut-finish\">Dokon\u010dit v\u00fdcvik</button>`;\n                document.getElementById('btn-tut-finish').onclick = () => this.endTutorial();\n                break;\n\n            default:\n                this.endTutorial();\n        }\n    },\n\n    endTutorial() {\n        this.clearTutorialGlows();\n\n        Storage.data.tutorialDone = true;\n        Storage.save();\n\n        this.tutActive = false;\n        this.holdFire = false;\n        this.tutStep = 0;\n\n        this.enemies.length = 0;\n        this.bullets.length = 0;\n        this.powerups.length = 0;\n        this.beams.length = 0;\n        this.shockwaves.length = 0;\n        this.boss = null;\n        this.bossActive = false;\n\n        this.player.hp = this.player.maxHp;\n        this.player.bombs = this.player.maxBombs;\n        // Cvi\u010dn\u00fd \u0161t\u00edt, trojst\u0159el nebo rychlopalba nesm\u00ed p\u0159e\u017e\u00edt do ostr\u00e9 hry\n        this.player.tripleShotTimer = 0;\n        this.player.shieldTimer = 0;\n        this.player.rapidTimer = 0;\n        this.player.invulnTimer = 0;\n\n        document.getElementById('boss-bar').classList.add('hidden');\n        document.getElementById('tut-layer').classList.add('hidden');\n\n        // Kdo si vybral Boss Rush je\u0161t\u011b p\u0159ed prvn\u00edm v\u00fdcvikem, dostane sv\u00e9ho prvn\u00edho bosse a\u017e te\u010f\n        if (this.mode === 'rush') this.spawnRushBoss();\n    }\n});\n\n//======================================================================\n//  OBCHOD A ROZHRAN\u00cd\n//======================================================================\n\n// Cena roste exponenci\u00e1ln\u011b, ne line\u00e1rn\u011b - \u010dasn\u00e1 vylep\u0161en\u00ed jsou levn\u00e1 pro rychl\u00fd\n// pocit pokroku, pozdn\u00ed jsou v\u00fdrazn\u011b dra\u017e\u0161\u00ed, aby vymaxov\u00e1n\u00ed cel\u00e9 lodi bylo\n// ot\u00e1zkou des\u00edtek minut hran\u00ed, ne p\u00e1r kol. Kalibrov\u00e1no simulac\u00ed skute\u010dn\u00e9 hry.\nconst UPGRADE_COST_MULT = 6;\nconst UPGRADE_COST_GROWTH = 1.30;\n\nfunction upgradeCost(up, level) {\n    return Math.round(up.step * UPGRADE_COST_MULT * Math.pow(UPGRADE_COST_GROWTH, level - 1));\n}\n\nconst UPGRADES = [\n    { key: 'fireRate', name: 'Rychlost palby', step: 10, effect: l => {\n        const relicFire = Achv.hasRelic('quickhand') ? 0.85 : 1;\n        const rate = Math.max(90, Math.round(Math.max(120, 430 - l * 16) * relicFire));\n        return `${(1000 / rate).toFixed(1)} salv za sekundu`;\n    } },\n    { key: 'damage', name: 'S\u00edla po\u0161kozen\u00ed', step: 15, effect: l => {\n        const asc = Storage.data.ascension || 0;\n        // Bonus siln\u011b sl\u00e1bne po 15. vzestupu - hodn\u011b vzestoupen\u00fd hr\u00e1\u010d nem\u00e1 b\u00fdt rychlej\u0161\u00ed,\n        // jen odoln\u011bj\u0161\u00ed. Skute\u010dn\u00e1 odm\u011bna za dal\u0161\u00ed vzestupy jde do Hv\u011bzdn\u00e9ho prachu.\n        const ascMul = 1 + Math.min(asc, 15) * 0.025 + Math.max(0, asc - 15) * 0.006;\n        const relicDmg = Achv.hasRelic('barrel') ? 1.2 : 1;\n        return `${Math.round((l + 1) * ascMul * relicDmg)} po\u0161kozen\u00ed za st\u0159elu`;\n    } },\n    { key: 'hp', name: 'Maxim\u00e1ln\u00ed \u017eivot', step: 10, effect: l => {\n        const asc = Storage.data.ascension || 0;\n        // Bonus siln\u011b sl\u00e1bne po 15. vzestupu - hodn\u011b vzestoupen\u00fd hr\u00e1\u010d nem\u00e1 b\u00fdt rychlej\u0161\u00ed,\n        // jen odoln\u011bj\u0161\u00ed. Skute\u010dn\u00e1 odm\u011bna za dal\u0161\u00ed vzestupy jde do Hv\u011bzdn\u00e9ho prachu.\n        const ascMul = 1 + Math.min(asc, 15) * 0.025 + Math.max(0, asc - 15) * 0.006;\n        const relicHp = Achv.hasRelic('plating') ? 1.15 : 1;\n        const hullMul = 1 + prestigeBonus('hull', 0.02);\n        return `${Math.round((80 + l * 20) * ascMul * relicHp * hullMul)} bod\u016f \u017eivota`;\n    } },\n    { key: 'bombs', name: 'Z\u00e1soba bomb \ud83d\udca3', step: 25, effect: l => {\n        const relicBombs = Achv.hasRelic('bombs') ? 1 : 0;\n        const prestigeBombs = prestigeLevel('bomb');\n        return `${Math.min(7, 1 + Math.floor((l - 1) / 3) + relicBombs + prestigeBombs)} na za\u010d\u00e1tku hry`;\n    } },\n    { key: 'shieldDuration', name: 'Trv\u00e1n\u00ed \u0161t\u00edtu \ud83d\udee1\ufe0f', step: 12, effect: l => {\n        const auraMul = 1 + prestigeBonus('aura', 0.04);\n        return `${((5000 + (l - 1) * 450) * auraMul / 1000).toFixed(1)} sekundy`;\n    } },\n    { key: 'tripleDuration', name: 'Trv\u00e1n\u00ed trojst\u0159elu \u26a1', step: 12, effect: l => {\n        const auraMul = 1 + prestigeBonus('aura', 0.04);\n        return `${((7000 + (l - 1) * 550) * auraMul / 1000).toFixed(1)} sekundy`;\n    } },\n    { key: 'rapidDuration', name: 'Trv\u00e1n\u00ed rychlopalby \ud83d\udd25', step: 12, effect: l => {\n        const auraMul = 1 + prestigeBonus('aura', 0.04);\n        return `${((6000 + (l - 1) * 500) * auraMul / 1000).toFixed(1)} sekundy`;\n    } },\n    { key: 'healPower', name: '\u00da\u010dinek l\u00e9k\u00e1rni\u010dky \u2764\ufe0f', step: 15, effect: l => `+${25 + (l - 1) * 10} \u017eivota` }\n];\n\n//======================================================================\n//  \u00daSP\u011aCHY A RELIKVIE\n//======================================================================\n//  Relikvie se neodemykaj\u00ed za mince, ale hran\u00edm - jsou to trval\u00e9 stopy\n//  po tom, co hr\u00e1\u010d ve h\u0159e dok\u00e1zal. Ka\u017ed\u00e1 relikvie vis\u00ed na jednom \u00fasp\u011bchu.\n\nconst ACHIEVEMENTS = [\n    { id: 'first_blood', name: 'Prvn\u00ed krev', desc: 'Zni\u010d sv\u00e9ho prvn\u00edho nep\u0159\u00edtele.', reward: 20,\n        check: s => s.totalKills >= 1 },\n    { id: 'hunter_100', name: 'Lovec', desc: 'Zni\u010d 100 nep\u0159\u00e1tel.', reward: 50,\n        check: s => s.totalKills >= 100, progress: s => [s.totalKills, 100] },\n    { id: 'hunter_300', name: 'Vyhlazova\u010d', desc: 'Zni\u010d 300 nep\u0159\u00e1tel. Odemyk\u00e1 relikvii Pos\u00edlen\u00e1 hlave\u0148.', reward: 150, relic: 'barrel',\n        check: s => s.totalKills >= 300, progress: s => [s.totalKills, 300] },\n    { id: 'hunter_1500', name: 'Zk\u00e1za hv\u011bzd', desc: 'Zni\u010d 1500 nep\u0159\u00e1tel.', reward: 400,\n        check: s => s.totalKills >= 1500, progress: s => [s.totalKills, 1500] },\n\n    { id: 'boss_first', name: 'Prvn\u00ed p\u00e1d', desc: 'Poraz sv\u00e9ho prvn\u00edho bosse.', reward: 40,\n        check: s => s.totalBossKills >= 1 },\n    { id: 'boss_10', name: 'Postrach boss\u016f', desc: 'Poraz 10 boss\u016f. Odemyk\u00e1 relikvii Siln\u00e9 pl\u00e1ty.', reward: 200, relic: 'plating',\n        check: s => s.totalBossKills >= 10, progress: s => [s.totalBossKills, 10] },\n    { id: 'boss_30', name: 'Extermin\u00e1tor', desc: 'Poraz 30 boss\u016f.', reward: 500,\n        check: s => s.totalBossKills >= 30, progress: s => [s.totalBossKills, 30] },\n    { id: 'no_hit_boss', name: 'Bez \u0161kr\u00e1bnut\u00ed', desc: 'Poraz bosse, ani\u017e bys v souboji dostal z\u00e1sah.', reward: 150,\n        check: s => s.noHitBosses >= 1 },\n\n    { id: 'combo_4', name: '\u0158et\u011bzov\u00e1 reakce', desc: 'Dos\u00e1hni n\u00e1sobi\u010de kombo \u00d74.', reward: 30,\n        check: s => (s.bestCombo || 0) >= 4 },\n    { id: 'combo_8', name: 'Nezastaviteln\u00fd', desc: 'Dos\u00e1hni n\u00e1sobi\u010de kombo \u00d78. Odemyk\u00e1 relikvii Rychl\u00e1 ruka.', reward: 100, relic: 'quickhand',\n        check: s => (s.bestCombo || 0) >= 8 },\n\n    { id: 'bomb_20', name: 'Demolice', desc: 'Pou\u017eij bomby 20\u00d7. Odemyk\u00e1 relikvii Nouzov\u00e9 bomby.', reward: 80, relic: 'bombs',\n        check: s => s.bombsUsed >= 20, progress: s => [s.bombsUsed, 20] },\n\n    { id: 'coins_5000', name: 'Boh\u00e1\u010d', desc: 'Vyd\u011blej za \u017eivot 5 000 minc\u00ed. Odemyk\u00e1 relikvii Sb\u011bra\u010d.', reward: 100, relic: 'collector',\n        check: s => s.totalCoinsEarned >= 5000, progress: s => [Math.min(s.totalCoinsEarned, 5000), 5000] },\n    { id: 'coins_50000', name: 'Magn\u00e1t', desc: 'Vyd\u011blej za \u017eivot 50 000 minc\u00ed.', reward: 300,\n        check: s => s.totalCoinsEarned >= 50000, progress: s => [Math.min(s.totalCoinsEarned, 50000), 50000] },\n\n    { id: 'survivor_10', name: 'Vytrvalec', desc: 'P\u0159e\u017eij 10 minut v jednom b\u011bhu.', reward: 100,\n        check: s => (s.longestRun || 0) >= 600000 },\n    { id: 'survivor_20', name: '\u017delezn\u00e9 pl\u00edce', desc: 'P\u0159e\u017eij 20 minut v jednom b\u011bhu.', reward: 250,\n        check: s => (s.longestRun || 0) >= 1200000 },\n\n    { id: 'blitz_clear', name: 'Bleskov\u00fd \u00fatok', desc: 'Dokon\u010di cel\u00e9 kolo Bleskov\u00e1 vlna.', reward: 60,\n        check: s => (s.blitzClears || 0) >= 1 },\n    { id: 'rush_5', name: 'N\u00e1jezdn\u00edk', desc: 'V Boss Rush poraz 5 boss\u016f v jedn\u00e9 s\u00e9rii.', reward: 150,\n        check: s => (s.bestRushStreak || 0) >= 5 },\n    { id: 'rush_10', name: 'Legenda n\u00e1jezd\u016f', desc: 'V Boss Rush poraz 10 boss\u016f v jedn\u00e9 s\u00e9rii.', reward: 400,\n        check: s => (s.bestRushStreak || 0) >= 10 },\n\n    { id: 'ascend_1', name: 'Vzestup', desc: 'Poprv\u00e9 vzestup. Odemyk\u00e1 relikvii F\u00e9nixovo j\u00e1dro.', reward: 0, relic: 'phoenix',\n        check: (s, d) => (d.ascension || 0) >= 1 },\n    { id: 'maxed_all', name: 'Dokonal\u00e1 lo\u010f', desc: 'Vylep\u0161i v\u0161ech osm kategori\u00ed na maximum.', reward: 300,\n        check: (s, d) => UPGRADES.every(u => (d.upgrades[u.key] || 1) >= MAX_LVL) }\n];\n\nconst RELICS = [\n    { id: 'barrel', name: 'Pos\u00edlen\u00e1 hlave\u0148', desc: '+20 % po\u0161kozen\u00ed.', requires: 'hunter_300' },\n    { id: 'plating', name: 'Siln\u00e9 pl\u00e1ty', desc: '+15 % maxim\u00e1ln\u00edho \u017eivota.', requires: 'boss_10' },\n    { id: 'quickhand', name: 'Rychl\u00e1 ruka', desc: '-15 % prodleva mezi v\u00fdst\u0159ely.', requires: 'combo_8' },\n    { id: 'bombs', name: 'Nouzov\u00e9 bomby', desc: '+1 k maxim\u00e1ln\u00edmu po\u010dtu bomb.', requires: 'bomb_20' },\n    { id: 'collector', name: 'Sb\u011bra\u010d', desc: '+20 % vyd\u011blan\u00fdch minc\u00ed.', requires: 'coins_5000' },\n    { id: 'phoenix', name: 'F\u00e9nixovo j\u00e1dro', desc: 'Jednou za b\u011bh p\u0159e\u017eije\u0161 smrt\u00edc\u00ed z\u00e1sah s 1 HP.', requires: 'ascend_1' }\n];\n\n//======================================================================\n//  HV\u011aZDN\u00dd PRACH - STROM VZESTUPU\n//======================================================================\n//  Vzestup d\u00e1v\u00e1 samostatnou m\u011bnu (hv\u011bzdn\u00fd prach), ne p\u0159\u00edmo hern\u00ed zrychlen\u00ed.\n//  Uzly stromu jsou schv\u00e1ln\u011b stropovan\u00e9 nebo ploch\u00e9, ne procentu\u00e1ln\u00ed bez\n//  limitu - hodn\u011b vzestoupen\u00fd hr\u00e1\u010d m\u00e1 b\u00fdt odoln\u011bj\u0161\u00ed a pohodln\u011bj\u0161\u00ed na hran\u00ed,\n//  ne rychlej\u0161\u00ed. Jedin\u00e9 dva \"siln\u00e9\" uzly jsou jednor\u00e1zov\u00e9 odem\u010den\u00ed nov\u00fdch\n//  re\u017eim\u016f, ne trval\u00fd n\u00e1sobi\u010d.\n\nconst PRESTIGE_TREE = [\n    { id: 'hull', name: 'Pevn\u011bj\u0161\u00ed trup', desc: '+2 % max. \u017eivota za \u00farove\u0148.', max: 10,\n        cost: lvl => 40 * (lvl + 1) },\n    { id: 'aura', name: 'Ochrann\u00e1 aura', desc: '+4 % trv\u00e1n\u00ed \u0161t\u00edtu, trojst\u0159elu a rychlopalby za \u00farove\u0148.', max: 8,\n        cost: lvl => 50 * (lvl + 1) },\n    { id: 'magnet', name: 'Magnetick\u00e9 j\u00e1dro', desc: '+10 % dosahu p\u0159ita\u017een\u00ed power-up\u016f za \u00farove\u0148.', max: 6,\n        cost: lvl => 35 * (lvl + 1) },\n    { id: 'luck', name: '\u0160\u0165astn\u00e1 hv\u011bzda', desc: '+1 % \u0161ance na power-up z nep\u0159\u00edtele za \u00farove\u0148.', max: 5,\n        cost: lvl => 60 * (lvl + 1) },\n    { id: 'capital', name: 'Startovn\u00ed kapit\u00e1l', desc: '+150 minc\u00ed na za\u010d\u00e1tku ka\u017ed\u00e9 hry za \u00farove\u0148.', max: 5,\n        cost: lvl => 30 * (lvl + 1) },\n    { id: 'bomb', name: 'Rezervn\u00ed bomba', desc: '+1 k maxim\u00e1ln\u00edmu po\u010dtu bomb.', max: 1,\n        cost: () => 500 },\n    { id: 'zenUnlocked', name: 'Re\u017eim Zen', desc: 'Odemkne klidn\u00fd nekone\u010dn\u00fd re\u017eim bez um\u00edr\u00e1n\u00ed.', max: 1, unlock: true,\n        cost: () => 150 },\n    { id: 'dailyUnlocked', name: 'Denn\u00ed v\u00fdzva', desc: 'Odemkne denn\u00ed v\u00fdzvu s vlastn\u00edm \u017eeb\u0159\u00ed\u010dkem.', max: 1, unlock: true,\n        cost: () => 150 }\n];\n\nfunction prestigeLevel(id) {\n    const v = Storage.data.prestige[id];\n    return typeof v === 'boolean' ? (v ? 1 : 0) : (v || 0);\n}\n\nfunction prestigeBonus(id, perLevel) {\n    return prestigeLevel(id) * perLevel;\n}\n\nconst Toast = {\n    queue: [],\n    showing: false,\n\n    push(a) {\n        this.queue.push(a);\n        this.pump();\n    },\n\n    pump() {\n        if (this.showing || !this.queue.length) return;\n        this.showing = true;\n\n        const a = this.queue.shift();\n        const layer = document.getElementById('achv-toast-layer');\n        if (!layer) { this.showing = false; return; }\n\n        const el = document.createElement('div');\n        el.className = 'achv-toast';\n        el.innerHTML = `<span class=\"achv-toast-icon\">\ud83c\udfc6</span><div><div class=\"achv-toast-eyebrow\">\u00dasp\u011bch odem\u010den</div><div class=\"achv-toast-name\">${a.name}</div></div>`;\n        layer.appendChild(el);\n\n        requestAnimationFrame(() => el.classList.add('show'));\n\n        setTimeout(() => {\n            el.classList.remove('show');\n            setTimeout(() => {\n                layer.removeChild(el);\n                this.showing = false;\n                this.pump();\n            }, 320);\n        }, 2600);\n    }\n};\n\nconst Achv = {\n    hasRelic(id) {\n        const r = RELICS.find(x => x.id === id);\n        return !!(r && Storage.data.achievements[r.requires]);\n    },\n\n    check() {\n        const s = Storage.data.stats;\n        const d = Storage.data;\n        let changed = false;\n\n        for (const a of ACHIEVEMENTS) {\n            if (Storage.data.achievements[a.id]) continue;\n\n            if (a.check(s, d)) {\n                Storage.data.achievements[a.id] = true;\n                Storage.data.coins += a.reward;\n                Storage.data.cycleCoins = (Storage.data.cycleCoins || 0) + a.reward;\n                changed = true;\n                Toast.push(a);\n\n                // Nov\u00e1 relikvie se mus\u00ed projevit okam\u017eit\u011b, ne a\u017e v dal\u0161\u00edm b\u011bhu\n                if (Game && Game.player) Game.player.applyStats();\n            }\n        }\n\n        if (changed) Storage.queueSave();\n    }\n};\n\n//======================================================================\n//  OBCHOD A ROZHRAN\u00cd\n//======================================================================\n\nconst UI = {\n    renderShop(containerId) {\n        const el = document.getElementById(containerId);\n        if (!el) return;\n\n        const u = Storage.data.upgrades;\n        const coins = Storage.data.coins || 0;\n\n        el.innerHTML = UPGRADES.map(up => {\n            const lvl = u[up.key] || 1;\n            const maxed = lvl >= MAX_LVL;\n            const cost = upgradeCost(up, lvl);\n            const afford = coins >= cost;\n\n            const btn = maxed\n                ? `<button class=\"btn btn-small btn-buy maxed\" disabled>Maximum</button>`\n                : `<button class=\"btn btn-small btn-buy ${afford ? '' : 'locked'}\" data-upgrade=\"${up.key}\">${U.num(cost)} m</button>`;\n\n            return `\n            <div class=\"upgrade-item ${maxed ? 'maxed' : ''}\">\n                <div class=\"upgrade-info\">\n                    <div class=\"upgrade-name\">${up.name}</div>\n                    <div class=\"upgrade-lvl\">\u00darove\u0148 ${lvl} z ${MAX_LVL} \u2014 <span class=\"upgrade-effect\">${up.effect(lvl)}</span></div>\n                </div>\n                ${btn}\n            </div>`;\n        }).join('');\n    },\n\n    refresh() {\n        const coins = U.num(Storage.data.coins || 0);\n        const best = Math.max(Storage.data.best.normal || 0, Storage.data.best.hard || 0);\n\n        document.getElementById('menu-coins').innerText = coins + ' minc\u00ed';\n        document.getElementById('pause-coins').innerText = coins + ' minc\u00ed';\n        document.getElementById('menu-best').innerText = 'Rekord ' + U.num(best);\n\n        const asc = Storage.data.ascension || 0;\n        const ascBadge = document.getElementById('menu-ascend');\n        ascBadge.classList.toggle('hidden', asc <= 0);\n        ascBadge.innerText = 'Vzestup ' + asc;\n\n        document.getElementById('rec-normal').innerText = 'Rekord ' + U.num(Storage.data.best.normal || 0);\n        document.getElementById('rec-hard').innerText = 'Rekord ' + U.num(Storage.data.best.hard || 0);\n        document.getElementById('rec-blitz').innerText = 'Rekord ' + U.num(Storage.data.best.blitz || 0);\n        document.getElementById('rec-rush').innerText = 'S\u00e9rie ' + U.num(Storage.data.best.rush || 0);\n\n        // Zen a Denn\u00ed v\u00fdzva se v menu objev\u00ed, a\u017e je hr\u00e1\u010d odemkne za hv\u011bzdn\u00fd prach\n        document.getElementById('btn-start-zen').classList.toggle('hidden', !Storage.data.prestige.zenUnlocked);\n        document.getElementById('btn-start-daily').classList.toggle('hidden', !Storage.data.prestige.dailyUnlocked);\n\n        if (Storage.data.prestige.dailyUnlocked) {\n            const mod = dailyModifierForToday();\n            document.getElementById('daily-desc').innerText = mod.name;\n            const today = todayKey();\n            const dailyScore = (Storage.data.daily.date === today) ? (Storage.data.daily.score || 0) : 0;\n            document.getElementById('rec-daily').innerText = 'Rekord ' + U.num(dailyScore);\n        }\n\n        this.renderShop('menu-shop');\n        this.renderShop('pause-shop');\n    },\n\n    buyUpgrade(key) {\n        const up = UPGRADES.find(x => x.key === key);\n        if (!up) return;\n\n        const lvl = Storage.data.upgrades[key] || 1;\n        if (lvl >= MAX_LVL) return;\n\n        const cost = upgradeCost(up, lvl);\n\n        // Bez odezvy vypad\u00e1 nedostatek minc\u00ed jako rozbit\u00e9 tla\u010d\u00edtko\n        if ((Storage.data.coins || 0) < cost) {\n            Sounds.denied();\n            document.querySelectorAll(`[data-upgrade=\"${key}\"]`).forEach(btn => {\n                btn.classList.remove('shake');\n                void btn.offsetWidth;\n                btn.classList.add('shake');\n            });\n            return;\n        }\n\n        Storage.data.coins -= cost;\n        Storage.data.upgrades[key] = lvl + 1;\n        Storage.save();\n        Sounds.buy();\n\n        if (Game.player) {\n            const before = Game.player.maxHp;\n            Game.player.applyStats();\n\n            // Vylep\u0161en\u00ed koupen\u00e9 b\u011bhem hry se mus\u00ed projevit hned, ne a\u017e p\u0159\u00ed\u0161t\u00ed kolo\n            if (key === 'hp') Game.player.hp = Math.min(Game.player.maxHp, Game.player.hp + (Game.player.maxHp - before));\n            if (key === 'bombs') Game.player.bombs = Math.min(Game.player.maxBombs, Game.player.bombs + 1);\n\n            Game.updateHUD(true);\n        }\n\n        Achv.check();\n        this.refresh();\n    },\n\n    toggleSound() {\n        Storage.data.muted = !Storage.data.muted;\n        Sounds.setMuted(Storage.data.muted);\n        Storage.save();\n        document.getElementById('btn-sound').innerText = Storage.data.muted ? '\ud83d\udd07' : '\ud83d\udd0a';\n    },\n\n    renderLifetimeStats(containerId) {\n        const s = Storage.data.stats;\n        const totalMin = Math.floor((s.totalPlaytime || 0) / 60000);\n\n        document.getElementById(containerId).innerHTML = `\n            <div><b>${U.num(s.totalKills || 0)}</b>nep\u0159\u00e1tel zni\u010deno</div>\n            <div><b>${U.num(s.totalBossKills || 0)}</b>boss\u016f pora\u017eeno</div>\n            <div><b>${U.num(s.totalCoinsEarned || 0)}</b>minc\u00ed vyd\u011bl\u00e1no</div>\n            <div><b>${U.num(totalMin)}</b>minut hran\u00ed</div>\n            <div><b>\u00d7${s.bestCombo || 1}</b>nejlep\u0161\u00ed kombo</div>\n            <div><b>${U.num(s.runsPlayed || 0)}</b>odehran\u00fdch her</div>`;\n    },\n\n    renderRelics(containerId) {\n        document.getElementById(containerId).innerHTML = RELICS.map(r => {\n            const unlocked = Achv.hasRelic(r.id);\n            return `<div class=\"relic-item ${unlocked ? 'unlocked' : 'locked'}\">\n                <div class=\"relic-name\">${unlocked ? '' : '\ud83d\udd12 '}${r.name}</div>\n                <div class=\"relic-desc\">${r.desc}</div>\n            </div>`;\n        }).join('');\n    },\n\n    renderAchievements(containerId) {\n        document.getElementById(containerId).innerHTML = ACHIEVEMENTS.map(a => {\n            const unlocked = !!Storage.data.achievements[a.id];\n            let progressHtml = '';\n\n            if (!unlocked && a.progress) {\n                const [cur, max] = a.progress(Storage.data.stats);\n                progressHtml = `<div class=\"achv-progress\">${U.num(Math.min(cur, max))} / ${U.num(max)}</div>`;\n            }\n\n            return `<div class=\"achv-item ${unlocked ? 'unlocked' : 'locked'}\">\n                <div class=\"achv-icon\">${unlocked ? '\ud83c\udfc6' : '\ud83d\udd12'}</div>\n                <div class=\"achv-body\">\n                    <div class=\"achv-name\">${a.name}</div>\n                    <div class=\"achv-desc\">${a.desc}</div>\n                    ${progressHtml}\n                </div>\n                <div class=\"achv-reward\">${a.reward > 0 ? '+' + a.reward : ''}</div>\n            </div>`;\n        }).join('');\n    },\n\n    renderPrestige(containerId) {\n        document.getElementById(containerId).innerHTML = PRESTIGE_TREE.map(node => {\n            const lvl = prestigeLevel(node.id);\n            const maxed = lvl >= node.max;\n            const cost = maxed ? 0 : node.cost(lvl);\n            const afford = (Storage.data.stardust || 0) >= cost;\n            const lvlLabel = node.unlock ? (maxed ? 'Odem\u010deno' : 'Zam\u010deno') : `\u00darove\u0148 ${lvl} z ${node.max}`;\n\n            const btn = maxed\n                ? `<button class=\"btn btn-small btn-prestige maxed\" disabled>${node.unlock ? 'Hotovo' : 'Max'}</button>`\n                : `<button class=\"btn btn-small btn-prestige ${afford ? '' : 'locked'}\" data-prestige=\"${node.id}\">${U.num(cost)} \u2726</button>`;\n\n            return `\n            <div class=\"prestige-item ${maxed ? 'maxed' : ''}\">\n                <div class=\"prestige-info\">\n                    <div class=\"prestige-name\">${node.name}</div>\n                    <div class=\"prestige-desc\">${node.desc}</div>\n                    <div class=\"prestige-lvl\">${lvlLabel}</div>\n                </div>\n                ${btn}\n            </div>`;\n        }).join('');\n    },\n\n    renderStats() {\n        this.renderLifetimeStats('lifetime-stats');\n        this.renderPrestige('prestige-list');\n        this.renderRelics('relic-list');\n        this.renderAchievements('achv-list');\n\n        document.getElementById('stardust-count').innerText = U.num(Storage.data.stardust || 0) + ' \u2726 prachu';\n\n        const allMaxed = UPGRADES.every(u => (Storage.data.upgrades[u.key] || 1) >= MAX_LVL);\n\n        document.getElementById('ascend-level').innerText = Storage.data.ascension || 0;\n        document.getElementById('ascend-desc').innerText = allMaxed\n            ? 'V\u0161e je na maximu. Vzestup vr\u00e1t\u00ed vylep\u0161en\u00ed na za\u010d\u00e1tek v\u00fdm\u011bnou za trval\u00fd bonus a hv\u011bzdn\u00fd prach.'\n            : 'Vylep\u0161i v\u0161ech osm kategori\u00ed na maximum, abys mohl vzestoupit.';\n\n        const btn = document.getElementById('btn-ascend');\n        btn.disabled = !allMaxed;\n        btn.classList.toggle('locked', !allMaxed);\n    }\n};\n\nfunction buyPrestigeNode(id) {\n    const node = PRESTIGE_TREE.find(n => n.id === id);\n    if (!node) return;\n\n    const lvl = prestigeLevel(id);\n    if (lvl >= node.max) return;\n\n    const cost = node.cost(lvl);\n\n    if ((Storage.data.stardust || 0) < cost) {\n        Sounds.denied();\n        document.querySelectorAll(`[data-prestige=\"${id}\"]`).forEach(btn => {\n            btn.classList.remove('shake');\n            void btn.offsetWidth;\n            btn.classList.add('shake');\n        });\n        return;\n    }\n\n    Storage.data.stardust -= cost;\n    Storage.data.prestige[id] = node.unlock ? true : lvl + 1;\n    Storage.save();\n    Sounds.buy();\n\n    if (Game.player) {\n        Game.player.applyStats();\n        Game.updateHUD(true);\n    }\n\n    UI.refresh();\n    UI.renderStats();\n}\n\nfunction performAscend() {\n    const allMaxed = UPGRADES.every(u => (Storage.data.upgrades[u.key] || 1) >= MAX_LVL);\n    if (!allMaxed) return;\n\n    // Hv\u011bzdn\u00fd prach je odm\u011bna za to, kolik hr\u00e1\u010d tento cyklus skute\u010dn\u011b vyd\u011blal -\n    // \u010d\u00edm d\u00e1l se dostal, t\u00edm v\u011bt\u0161\u00ed odm\u011bna, ale je to jin\u00e1 m\u011bna ne\u017e mince,\n    // tak\u017ee se s dal\u0161\u00edmi vzestupy nezrychluje samotn\u00e1 hra.\n    const earned = Math.max(5, Math.floor((Storage.data.cycleCoins || 0) / 800));\n\n    if (!confirm(`Vzestoupit? Vylep\u0161en\u00ed lodi se vr\u00e1t\u00ed na za\u010d\u00e1tek v\u00fdm\u011bnou za trval\u00fd bonus a ${earned} hv\u011bzdn\u00e9ho prachu.`)) return;\n\n    for (const k in Storage.data.upgrades) Storage.data.upgrades[k] = 1;\n    Storage.data.ascension = (Storage.data.ascension || 0) + 1;\n    Storage.data.stardust = (Storage.data.stardust || 0) + earned;\n    Storage.data.cycleCoins = 0;\n    // Startovn\u00ed kapit\u00e1l ze stromu Vzestupu d\u00e1 malou vzpruhu m\u00edsto tvrd\u00e9 nuly\n    Storage.data.coins = prestigeLevel('capital') * 150;\n    Storage.save();\n\n    Achv.check();\n\n    if (Game.player) {\n        Game.player.applyStats();\n        Game.player.hp = Game.player.maxHp;\n        Game.player.bombs = Game.player.maxBombs;\n    }\n\n    UI.refresh();\n    UI.renderStats();\n}\n\n//======================================================================\n//  START\n//======================================================================\n\nconst Game = new GameManager();\n\nUI.refresh();\ndocument.getElementById('btn-sound').innerText = Storage.data.muted ? '\ud83d\udd07' : '\ud83d\udd0a';\n\n['menu-shop', 'pause-shop'].forEach(id => {\n    document.getElementById(id).addEventListener('click', e => {\n        const btn = e.target.closest('[data-upgrade]');\n        if (btn) UI.buyUpgrade(btn.dataset.upgrade);\n    });\n});\n\ndocument.getElementById('btn-start-normal').onclick = () => Game.start('normal');\ndocument.getElementById('btn-start-hard').onclick = () => Game.start('hard');\ndocument.getElementById('btn-start-blitz').onclick = () => Game.start('blitz');\ndocument.getElementById('btn-start-rush').onclick = () => Game.start('rush');\ndocument.getElementById('btn-start-zen').onclick = () => Game.start('zen');\ndocument.getElementById('btn-start-daily').onclick = () => Game.start('daily');\ndocument.getElementById('btn-pause').onclick = () => Game.pause();\ndocument.getElementById('btn-resume').onclick = () => Game.resume();\ndocument.getElementById('btn-quit-pause').onclick = () => Game.quitToMenu();\ndocument.getElementById('btn-restart').onclick = () => Game.start(Game.mode);\ndocument.getElementById('btn-quit-go').onclick = () => Game.quitToMenu();\ndocument.getElementById('btn-sound').onclick = () => UI.toggleSound();\n\ndocument.getElementById('prestige-list').addEventListener('click', e => {\n    const btn = e.target.closest('[data-prestige]');\n    if (btn) buyPrestigeNode(btn.dataset.prestige);\n});\n\ndocument.getElementById('btn-open-stats').onclick = () => {\n    document.getElementById('menu-overlay').classList.add('hidden');\n    document.getElementById('stats-overlay').classList.remove('hidden');\n    UI.renderStats();\n};\n\ndocument.getElementById('btn-close-stats').onclick = () => {\n    document.getElementById('stats-overlay').classList.add('hidden');\n    document.getElementById('menu-overlay').classList.remove('hidden');\n};\n\ndocument.getElementById('btn-ascend').onclick = () => performAscend();\n\ndocument.getElementById('btn-bomb').addEventListener('pointerdown', e => {\n    e.preventDefault();\n    e.stopPropagation();\n    Game.useBomb();\n});\n\ndocument.getElementById('btn-reset').onclick = () => {\n    if (confirm('Opravdu smazat postup? P\u0159ijdete o mince, vylep\u0161en\u00ed, rekordy, \u00fasp\u011bchy, vzestup i hv\u011bzdn\u00fd prach.')) {\n        Storage.wipe();\n        Sounds.setMuted(false);\n        document.getElementById('btn-sound').innerText = '\ud83d\udd0a';\n        UI.refresh();\n        // Obrazovka Postupu sem dnes v\u00e9st nem\u016f\u017ee (btn-reset \u017eije jen v menu-overlay),\n        // ale kdyby se to v budoucnu zm\u011bnilo, a\u0165 nez\u016fstanou zobrazen\u00e1 smazan\u00e1 data\n        if (!document.getElementById('stats-overlay').classList.contains('hidden')) UI.renderStats();\n    }\n};\n\nconst secretBtn = document.getElementById('btn-secret');\nconst secretInput = document.getElementById('secret-input');\nconst secretMsg = document.getElementById('secret-msg');\nlet secretTimer = null;\n\nconst showSecretMsg = (text, color) => {\n    secretMsg.style.color = color;\n    secretMsg.innerText = text;\n\n    clearTimeout(secretTimer);\n    secretTimer = setTimeout(() => { secretMsg.innerText = ''; }, 2500);\n};\n\nconst applySecret = () => {\n    const code = secretInput.value.trim().toUpperCase();\n    if (!code) return;\n\n    if (code === '67MILUJU') {\n        Storage.data.coins = 999999999;\n        Storage.save();\n        UI.refresh();\n        secretInput.value = '';\n        showSecretMsg('K\u00f3d p\u0159ijat, mince dopln\u011bny.', '#00ff88');\n    } else {\n        showSecretMsg('Tenhle k\u00f3d nezn\u00e1m.', 'var(--danger)');\n    }\n};\n\nif (secretBtn && secretInput) {\n    secretBtn.onclick = applySecret;\n    secretInput.addEventListener('keydown', e => {\n        if (e.key === 'Enter') applySecret();\n    });\n}\n</script>\n</body>\n</html>\n";
